/* Java 中级 11 课正文内容注册表（由 frag-java 碎片自动生成）。
   key = track|stack|lessonName；article.html 命中后渲染真实正文，否则回退占位。 */
window.QZ_CONTENT = (function () {
  'use strict';
  var data = {
    "backend|java|六道关与模块设计": { "body": "<p class=\"lead\">初级关心「能不能做出来」，中级关心「多少人同时用、出错怎么办、事后能不能查清」。这一课不写新功能，先学会把「用户能跟 AI 聊天」拆成职责清楚的模块，再给每个模块定下能衡量的目标。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">拆需求</span><span class=\"s\">六道关</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">定目标</span><span class=\"s\">容量推导</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">划边界</span><span class=\"s\">模块不越界</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>一句需求，背后是六道关</h2>\n    <p>先讲个故事。小林最初摆路边摊：一口锅、一个人，客人点什么他炒什么，一天几十单挺顺。后来一天三千单，麻烦全来了——有人插队、有人拿错别人的菜、有人一次点两百份把锅占死、月底算账还对不上。他以为是「炒得不够快」，加了两口锅也没用。真正缺的是：<b>从来没规定谁点单、谁备料、谁收钱、谁记账</b>。</p>\n    <p>产品给你一句话：<span class=\"term\">「用户发消息给 AI，能实时看到回答，按 Token 扣费。」</span>这是<b>功能需求</b>——它只说「做什么」，没说「多少人同时发、多久要看到、错了怎么办」。只盯着它写代码，就会写出一个能跑、但全是坑的 <code>chat()</code> 方法。</p>\n    <p>中级第一件事，是把这句话拆成一条请求要闯的<b>六道关</b>，像过机场安检，每关只查一件事：</p>\n    <figure>\n      <svg viewBox=\"0 0 760 200\" role=\"img\" aria-label=\"一条请求要闯的六道关\">\n        <defs><marker id=\"arj1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <text x=\"8\" y=\"24\" font-size=\"12\" fill=\"#7C7166\">用户请求 →</text>\n        <rect x=\"8\" y=\"40\" width=\"112\" height=\"64\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"64\" y=\"66\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">① 认证授权</text><text x=\"64\" y=\"86\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">你是谁·能不能调</text>\n        <rect x=\"132\" y=\"40\" width=\"112\" height=\"64\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"188\" y=\"66\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">② 计量限流</text><text x=\"188\" y=\"86\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">配额·并发</text>\n        <rect x=\"256\" y=\"40\" width=\"112\" height=\"64\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"312\" y=\"66\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">③ 模型路由</text><text x=\"312\" y=\"86\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">选哪个厂商</text>\n        <rect x=\"380\" y=\"40\" width=\"112\" height=\"64\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"436\" y=\"66\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">④ 请求代理</text><text x=\"436\" y=\"86\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">转发·透传 SSE</text>\n        <rect x=\"504\" y=\"40\" width=\"112\" height=\"64\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"560\" y=\"66\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">⑤ 幂等韧性</text><text x=\"560\" y=\"86\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">重试·降级</text>\n        <rect x=\"628\" y=\"40\" width=\"124\" height=\"64\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"690\" y=\"66\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#5B4A2F\">⑥ 安全审计</text><text x=\"690\" y=\"86\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">谁·何时·调了什么</text>\n        <line x1=\"120\" y1=\"72\" x2=\"130\" y2=\"72\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1)\"/>\n        <line x1=\"244\" y1=\"72\" x2=\"254\" y2=\"72\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1)\"/>\n        <line x1=\"368\" y1=\"72\" x2=\"378\" y2=\"72\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1)\"/>\n        <line x1=\"492\" y1=\"72\" x2=\"502\" y2=\"72\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1)\"/>\n        <line x1=\"616\" y1=\"72\" x2=\"626\" y2=\"72\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1)\"/>\n        <text x=\"64\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">失败→401/403</text>\n        <text x=\"188\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">超限→429</text>\n        <text x=\"436\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">超时→重试/降级</text>\n        <text x=\"380\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" fill=\"#A39B8E\">每一关都有「成功 / 失败 / 未知」三种可能——设计质量就看你有没有把三种都想清楚</text>\n      </svg>\n      <figcaption>图 1 · 一条请求的六道关：每关只查一件事，失败各有出口。</figcaption>\n    </figure>\n    <p>把这六关写成「谁负责什么、不碰什么」的岗位表，就是<b>模块设计</b>。最常见的反模式，是把认证、路由、计费、重试全塞进一个 Service——改一个动作牵动整间厨房。</p>\n    <table>\n      <tr><th>模块</th><th>它负责什么</th><th>它不碰什么</th></tr>\n      <tr><td>认证授权</td><td>你是谁、你能不能调</td><td>调的是哪个模型</td></tr>\n      <tr><td>计量限流</td><td>按 Token 计费、控制并发</td><td>模型返回的质量</td></tr>\n      <tr><td>模型路由</td><td>按请求选模型和厂商</td><td>用户有没有权限</td></tr>\n      <tr><td>幂等韧性</td><td>重复不重处理、故障降级</td><td>认证逻辑</td></tr>\n      <tr><td>安全审计</td><td>记录谁何时调了什么</td><td>业务数据内容</td></tr>\n      <tr><td>可观测性</td><td>日志、指标、链路追踪</td><td>业务逻辑</td></tr>\n    </table>\n    <div class=\"key\"><span class=\"tag\">一句话记住</span>功能需求描述「客人能吃到菜」，模块责任描述「谁洗、谁切、谁炒、谁收钱」。前者是结果，后者是分工。</div>\n    <div class=\"recap\"><b>收束：</b>先把一句需求拆成六道关，每关一个模块、各管一摊、各有失败出口。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>把「要稳定」变成有来源的数字</h2>\n    <p>「系统要稳定」是一句没法验证的话。中级要把它变成一组<b>能推导、能压测</b>的数字。容量目标像餐厅门口贴的「最多同时接待 50 桌」——不是拍脑袋，是按灶台数、服务员数算出来的。</p>\n    <p>课程场景的推导链（每个数字都有来源）：</p>\n    <figure>\n      <svg viewBox=\"0 0 760 170\" role=\"img\" aria-label=\"容量目标推导链\">\n        <defs><marker id=\"arj1b\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"30\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"83\" y=\"54\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">日活 1 万</text><text x=\"83\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">× 每人 ~200 次/天</text>\n        <rect x=\"180\" y=\"30\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"255\" y=\"54\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">200 万次/天</text><text x=\"255\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">÷ 86400 秒</text>\n        <rect x=\"352\" y=\"30\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"427\" y=\"54\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">平均 ≈ 23 QPS</text><text x=\"427\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">× 峰值 20 倍</text>\n        <rect x=\"524\" y=\"30\" width=\"228\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"638\" y=\"54\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">峰值 ≈ 460 QPS</text><text x=\"638\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">设计目标取 500</text>\n        <line x1=\"158\" y1=\"58\" x2=\"178\" y2=\"58\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1b)\"/>\n        <line x1=\"330\" y1=\"58\" x2=\"350\" y2=\"58\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1b)\"/>\n        <line x1=\"502\" y1=\"58\" x2=\"522\" y2=\"58\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj1b)\"/>\n        <rect x=\"8\" y=\"108\" width=\"744\" height=\"48\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/>\n        <text x=\"380\" y=\"128\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5B4A2F\">并发 SSE 另算（Little's Law）：并发数 = 到达率 × 平均连接时长 = 67 QPS × 30 秒 ≈ 2000</text>\n        <text x=\"380\" y=\"146\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">⚠ 若峰值 500 里 80% 都是 30 秒的 SSE：500 × 0.8 × 30 = 12000，不是 2000！</text>\n      </svg>\n      <figcaption>图 2 · QPS 和并发连接数是两个指标，用错一个，线程池和连接池就设计错。</figcaption>\n    </figure>\n    <p>三类指标各管一件事：<span class=\"term2\">业务规模</span>（用户数、日活）决定要多大；<span class=\"term2\">性能</span>（QPS、P95 延迟、并发）决定要多快；<span class=\"term2\">可靠性</span>（可用性、恢复时间）决定要多稳。</p>\n    <table>\n      <tr><th>指标</th><th>课程目标</th><th>它决定什么</th></tr>\n      <tr><td>注册用户 / 日活</td><td>10 万 / 1 万</td><td>数据量级、存储方案</td></tr>\n      <tr><td>峰值请求</td><td>500 QPS</td><td>线程池容量、限流</td></tr>\n      <tr><td>并发 SSE 会话</td><td>2,000</td><td>连接管理、内存占用</td></tr>\n      <tr><td>网关附加延迟</td><td>P95 ≤ 50 ms</td><td>不含下游模型响应时间</td></tr>\n      <tr><td>可用性</td><td>99.9%</td><td>每年允许停机约 8.76 小时</td></tr>\n      <tr><td>配额扣减</td><td>不超扣、不重复扣</td><td>一致性最高优先级</td></tr>\n      <tr><td>单厂商故障切换</td><td>≤ 30 秒</td><td>熔断、降级时间要求</td></tr>\n    </table>\n    <p><code>99.9%</code> 不是「差不多稳定」，它有数学含义：</p>\n    <table>\n      <tr><th>可用性</th><th>年停机</th><th>月停机</th></tr>\n      <tr><td>99%（两个 9）</td><td>3.65 天</td><td>约 7.3 小时</td></tr>\n      <tr><td>99.9%（三个 9）</td><td>8.76 小时</td><td>约 43.8 分钟</td></tr>\n      <tr><td>99.99%（四个 9）</td><td>52.6 分钟</td><td>约 4.4 分钟</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">边界口径</span>中级主线是<b>模块化单体</b>：在同一个 Java 网关服务里把六块职责加厚，不预设拆成第二个独立服务。什么时候拆、按什么领域边界拆，留到高级再决策。所以「划边界」首先是<b>服务内模块之间</b>不越界——比如网关模块不该直接查业务用户表，权限信息由上游放在请求头里传进来。</div>\n    <p>关键决定要写 <span class=\"term\">ADR</span>（架构决策记录）：标题 + 状态 + 背景 + 方案对比 + 决策理由 + 影响 + 后续。它的「R」是 Record，记的是<b>推理过程</b>，不是结论——让半年后的你读懂当时为什么没选另一个方案。</p>\n    <div class=\"recap\"><b>收束：</b>每个容量数字都要有来源；QPS≠并发；99.9% 有数学含义；决定写进 ADR。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：写法对照、容量推导</h2>\n    <p>演练一看「一把梭」和「分模块」两种写法的差别。演练二拖动滑块，亲手把业务数字推成 QPS 和并发，体会 Little's Law 和那个 12000 的陷阱。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 两种写法</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e1\"><button data-k=\"api\" class=\"on\">❌ 一把梭</button><button data-k=\"cmp\">✅ 分模块</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e1code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个需求，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 容量推导沙盒</b><span class=\"hint\">拖滑块，看数字怎么来的</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>日活(千)</label><input type=\"range\" id=\"g1dau\" min=\"1\" max=\"50\" value=\"10\"><span class=\"val\" id=\"g1dauV\">10</span></div>\n        <div class=\"ctl\"><label>每人/天</label><input type=\"range\" id=\"g1per\" min=\"20\" max=\"400\" value=\"200\"><span class=\"val\" id=\"g1perV\">200</span></div>\n        <div class=\"ctl\"><label>峰值倍数</label><input type=\"range\" id=\"g1peak\" min=\"5\" max=\"30\" value=\"20\"><span class=\"val\" id=\"g1peakV\">20</span></div>\n        <div class=\"ctl\"><label>SSE到达率</label><input type=\"range\" id=\"g1arr\" min=\"10\" max=\"200\" value=\"67\"><span class=\"val\" id=\"g1arrV\">67</span></div>\n        <div class=\"ctl\"><label>连接时长(s)</label><input type=\"range\" id=\"g1dur\" min=\"5\" max=\"60\" value=\"30\"><span class=\"val\" id=\"g1durV\">30</span></div>\n        <div class=\"ctl\"><label><input type=\"checkbox\" id=\"g1sse\"> 峰值80%是SSE</label></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g1stats\"></div><div class=\"chips\" id=\"g1chips\"></div><div class=\"key\" id=\"g1hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>推导过程</span><span>live</span></div><div class=\"logcat-body\" id=\"g1log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">目标：峰值 ≤ 500 QPS，并发 SSE ≤ 2000</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>分模块不是多写代码，是让每个失败都有人负责。容量不是抄数字，是每个中间值都能说出来源。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你已经会用「设计」的眼睛看一个系统了。下一课钻进 JVM 看人和台面。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>概念</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>功能需求</td><td>系统要做成什么事</td><td>「发消息能看到回答」</td></tr>\n      <tr><td>非功能需求</td><td>多快、多稳、扛多少人</td><td>QPS / P95 / 可用性 / 并发</td></tr>\n      <tr><td>模块边界</td><td>谁管什么、不碰什么</td><td>别全塞一个 Service</td></tr>\n      <tr><td>容量推导</td><td>每个数字有来源</td><td>日活×频次÷86400×峰值倍数</td></tr>\n      <tr><td>Little's Law</td><td>并发 = 到达率 × 时长</td><td>QPS ≠ 并发连接数</td></tr>\n      <tr><td>ADR</td><td>把决定和理由写成一张纸</td><td>记推理，不只记结论</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，容量数字为课程场景假设（第九篇压测验证）；并发模型与模块化单体口径以课程 README 为准。演练为模拟推导，非真实压测。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第一篇-中级导学与模块设计 <span class=\"src\">— 本课重写底稿，叙事按 README 模块化单体口径同步</span></li>\n        <li>中级工程师/README.md <span class=\"src\">— 容量场景、贯穿规则、课程边界的权威口径</span></li>\n      </ul>\n      <h3>方法与规范</h3>\n      <ul>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR · Architecture Decision Records</a> <span class=\"src\">— 架构决策记录的格式与模板</span></li>\n        <li>Little's Law（利特尔法则）<span class=\"src\">— 排队论基本公式：并发数 = 到达率 × 平均停留时间，见推导链图 2</span></li>\n      </ul>\n      <h3>下一课要用</h3>\n      <ul>\n        <li><a href=\"https://openjdk.org/jeps/444\" target=\"_blank\" rel=\"noopener\">JEP 444: Virtual Threads</a> <span class=\"src\">— JDK 21 虚拟线程，J2 主线并发模型</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"六道关"},{"id":"b","title":"容量推导"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 一把梭：功能做出来了，坑全埋着\\n@PostMapping(\\\"/chat\\\")\\npublic Flux<ChatResponse> chat(@RequestBody ChatRequest req) {\\n    return aiService.chat(req);  // 认证?配额?超时?重复扣费? 全没管\\n}\";\n  var CMP=\"// ✅ 分模块：每关一个职责，各有失败出口\\n@PostMapping(\\\"/chat\\\")\\npublic SseEmitter chat(@RequestBody ChatRequest req) {\\n    auth.check(req);            // ① 认证授权 → 401/403\\n    quota.reserve(req);         // ② 计量限流 → 429\\n    var route = router.pick(req); // ③ 模型路由\\n    return proxy.stream(route, req); // ④ 代理 ⑤ 幂等韧性 ⑥ 审计\\n}\";\n  function show(k){document.getElementById(\"e1code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e1log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"能跑，但每个失败都没人负责\":\"每个模块只管一摊，出事能找到人\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"改一处牵动全身，测试测不透\":\"边界清楚，可独立测试、独立监控\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e1 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e1 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：容量推导沙盒\n(function(){\n  var ids=['dau','per','peak','arr','dur'];\n  function val(id){return parseInt(document.getElementById('g1'+id).value,10);}\n  function calc(){\n    ids.forEach(function(id){document.getElementById('g1'+id+'V').textContent=val(id);});\n    var dau=val('dau')*1000, per=val('per'), peak=val('peak'), arr=val('arr'), dur=val('dur');\n    var daily=dau*per;\n    var avg=daily/86400;\n    var peakQps=avg*peak;\n    var sseOn=document.getElementById('g1sse').checked;\n    var conc = sseOn ? peakQps*0.8*dur : arr*dur;\n    var okP=peakQps<=500, okC=conc<=2000;\n    document.getElementById('g1stats').innerHTML=\n      '<div class=\"stat-box\"><b>'+avg.toFixed(1)+'</b><small>平均 QPS</small></div>'+\n      '<div class=\"stat-box '+(okP?'good':'bad')+'\"><b>'+Math.round(peakQps)+'</b><small>峰值 QPS</small></div>'+\n      '<div class=\"stat-box '+(okC?'good':'bad')+'\"><b>'+Math.round(conc)+'</b><small>并发 SSE</small></div>';\n    document.getElementById('g1chips').innerHTML=\n      '<span class=\"chip '+(okP?'on':'bad')+'\">峰值 '+(okP?'≤500 达标':'>500 超标')+'</span>'+\n      '<span class=\"chip '+(okC?'on':'bad')+'\">并发 '+(okC?'≤2000 达标':'>2000 超标')+'</span>'+\n      (sseOn?'<span class=\"chip bad\">陷阱模式：80% SSE</span>':'');\n    document.getElementById('g1hint').innerHTML='<span class=\"tag\">'+(sseOn?'陷阱':'推导')+'</span>'+\n      (sseOn?'峰值里 80% 是 30 秒 SSE 时，并发 = 峰值×0.8×时长，会冲到上万。必须分别定义总 QPS、流式到达率和连接时长。':'并发用的是流式到达率 '+arr+' QPS × 时长 '+dur+'s（Little\\'s Law），不是峰值 QPS。两者差好几倍。');\n    document.getElementById('g1log').innerHTML=[\n      '<div><span class=\"api\">日请求 = '+dau+' × '+per+' = '+daily.toLocaleString()+' 次/天</span></div>',\n      '<div><span class=\"ok\">平均 QPS = '+daily.toLocaleString()+' ÷ 86400 ≈ '+avg.toFixed(1)+'</span></div>',\n      '<div><span class=\"ok\">峰值 QPS = '+avg.toFixed(1)+' × '+peak+' ≈ '+Math.round(peakQps)+'</span></div>',\n      sseOn?'<div><span class=\"warn\">并发 = '+Math.round(peakQps)+' × 0.8 × '+dur+' ≈ '+Math.round(conc)+' ⚠</span></div>':'<div><span class=\"ok\">并发 SSE = '+arr+' × '+dur+' ≈ '+Math.round(conc)+'</span></div>',\n      '<div><span class=\"c\">// '+(okP&&okC?'两项都在课程目标内':'有指标超标，需要重新设计或缩流量')+'</span></div>'\n    ].join('');\n  }\n  ids.forEach(function(id){document.getElementById('g1'+id).addEventListener('input',calc);});\n  document.getElementById('g1sse').addEventListener('change',calc);\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. 「用户能跟 AI 聊天」属于？\",\"opts\":[[\"功能需求\",true,\"对。它只说做什么。\"],[\"非功能需求\",false,\"那是多快多稳。\"],[\"模块边界\",false,\"那是分工。\"]]},{\"q\":\"2. 模块设计回答的是？\",\"opts\":[[\"谁管什么、不碰什么\",true,\"对。分工。\"],[\"系统做什么\",false,\"那是功能需求。\"],[\"代码怎么写\",false,\"先设计再编码。\"]]},{\"q\":\"3. 平均 QPS 怎么推？\",\"opts\":[[\"日请求数 ÷ 86400\",true,\"对。每个数字有来源。\"],[\"直接拍 500\",false,\"拍出来的没法设计。\"],[\"日活 × 20\",false,\"那是日请求数。\"]]},{\"q\":\"4. 并发 SSE 连接数用什么算？\",\"opts\":[[\"到达率 × 平均连接时长（Little's Law）\",true,\"对。67×30≈2000。\"],[\"峰值 QPS 就是并发\",false,\"两个不同指标。\"],[\"日活 ÷ 24\",false,\"无关。\"]]},{\"q\":\"5. 99.9% 可用性意味着每年允许停机约？\",\"opts\":[[\"8.76 小时\",true,\"对。三个 9。\"],[\"3.65 天\",false,\"那是 99%。\"],[\"52.6 分钟\",false,\"那是 99.99%。\"]]},{\"q\":\"6. ADR 的「R」记录的是什么？\",\"opts\":[[\"推理过程：为什么没选另一个方案\",true,\"对。Record 记理由不只记结论。\"],[\"只记最终结论\",false,\"等于没记。\"],[\"代码实现\",false,\"那是源码。\"]]}];" },
    "backend|java|JVM 线程与诊断": { "body": "<p class=\"lead\">上一课定好了岗位，这一课钻进厨房看「人和台面」。服务员（线程）等菜、操作台（堆）摆菜、收台阿姨（GC）收盘子。学会看懂一次请求怎么占线程和内存，按用途把线程池隔开，再用工具证据定位「为什么慢、为什么崩」。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">后厨地图</span><span class=\"s\">堆·栈·GC</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">线程模型</span><span class=\"s\">隔离·虚拟线程</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">诊断</span><span class=\"s\">jstack·jmap·JFR</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>把 JVM 想成一间后厨</h2>\n    <p>高峰期一下来了 2000 桌，每桌都要一个服务员站着等菜。正式服务员只有 20 个，剩下 1980 桌干等；换成「随叫随到的临时工」（虚拟线程），人是不缺了，可灶台还是两个，菜照样出不来。这一课要回答：<b>什么时候加人、什么时候加灶，卡住时怎么靠收台记录和监控录像找出堵在哪一步</b>。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 230\" role=\"img\" aria-label=\"JVM 后厨地图\">\n        <rect x=\"8\" y=\"30\" width=\"360\" height=\"180\" rx=\"12\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/>\n        <text x=\"188\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#8A5510\">堆 Heap · 公共操作台</text>\n        <rect x=\"24\" y=\"66\" width=\"150\" height=\"56\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"99\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">新生代 Eden</text><text x=\"99\" y=\"108\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">刚做的菜·用完就清</text>\n        <rect x=\"190\" y=\"66\" width=\"160\" height=\"56\" rx=\"9\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"270\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">老年代 Old</text><text x=\"270\" y=\"108\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">冷藏柜·长期存</text>\n        <rect x=\"24\" y=\"134\" width=\"326\" height=\"56\" rx=\"9\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"187\" y=\"158\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">GC 收台阿姨</text><text x=\"187\" y=\"176\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">Minor 收新生代 · Full 全店停手（STW）</text>\n        <rect x=\"384\" y=\"30\" width=\"180\" height=\"86\" rx=\"12\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"474\" y=\"54\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">栈 Stack</text><text x=\"474\" y=\"74\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">服务员的点单本</text><text x=\"474\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">一人一本·用完就扔</text>\n        <rect x=\"580\" y=\"30\" width=\"172\" height=\"86\" rx=\"12\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"666\" y=\"54\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">元空间 Metaspace</text><text x=\"666\" y=\"74\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">墙上的菜谱</text><text x=\"666\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">全店共用一份</text>\n        <rect x=\"384\" y=\"130\" width=\"368\" height=\"80\" rx=\"12\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"568\" y=\"156\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5B4A2F\">对象的一生</text><text x=\"568\" y=\"176\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7C7166\">new → Eden → 熬过多次 Minor GC → 晋升 Old → Full GC 回收</text><text x=\"568\" y=\"194\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#B04A35\">SSE 长连接对象活得久，容易晋升老年代</text>\n      </svg>\n      <figcaption>图 1 · 线程决定「能同时接多少单」，内存决定「能同时摆多少菜」，GC 决定「收台会不会让全店停一下」。</figcaption>\n    </figure>\n    <table>\n      <tr><th>区域</th><th>存什么</th><th>大白话</th></tr>\n      <tr><td>堆 · 新生代 Eden</td><td>刚创建的新对象</td><td>备餐台，GC 频繁打扫</td></tr>\n      <tr><td>堆 · 老年代 Old</td><td>存活久的对象</td><td>冷藏柜，较少回收</td></tr>\n      <tr><td>元空间 Metaspace</td><td>类定义、常量、静态字段</td><td>墙上菜谱（JDK 8+ 在堆外）</td></tr>\n      <tr><td>虚拟机栈 Stack</td><td>方法调用、局部变量</td><td>服务员点单本，每线程一个</td></tr>\n    </table>\n    <p>用户感到「突然卡一下」，答案常在 <span class=\"term\">GC 日志</span>里。重点不是阿姨忙不忙，而是她每次收台有没有让全店停手（STW）、停了多久：</p>\n    <table>\n      <tr><th>GC 类型</th><th>触发</th><th>暂停</th><th>对网关（P95≤50ms）</th></tr>\n      <tr><td>Minor GC</td><td>Eden 满</td><td>几~几十 ms</td><td>可接受</td></tr>\n      <tr><td>Major GC</td><td>老年代满</td><td>几十~几百 ms</td><td>可能超时</td></tr>\n      <tr><td>Full GC</td><td>整堆回收</td><td>几百 ms~几秒</td><td>服务卡死</td></tr>\n    </table>\n    <pre><span class=\"cm\"># JDK 11+ 开 GC 日志（收台记录）</span>\n-Xlog:gc*:file=/var/log/app/gc.log:time,level,tags:filecount=5,filesize=50m\n<span class=\"cm\"># 看到 [Full GC ... 0.5678901 secs] → 暂停 567ms，远超 50ms 目标</span></pre>\n    <div class=\"key\"><span class=\"tag\">网关内存关注点</span>SSE 长连接持有请求对象和响应缓冲：2000 连接 × 每个 1MB = 2GB。<b>逐块转发、别把完整响应长期缓存在堆里</b>；缓存要有 TTL 和大小限制，否则只增不减就是泄漏。</div>\n    <div class=\"recap\"><b>收束：</b>堆摆菜、栈点单、GC 收台；看 GC 日志的 STW 时长，而不是只看「内存高不高」。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>线程池隔离与虚拟线程</h2>\n    <p>最危险的写法是<b>一个池干所有活</b>：认证、路由、AI 调用共用一个线程池，一个慢的 AI 调用占满整个池，其他所有请求都排队。正确做法是按用途隔离——一个池堵了不拖垮别的池。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"线程池隔离\">\n        <defs><marker id=\"arj2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"60\" width=\"120\" height=\"56\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"68\" y=\"84\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5B4A2F\">请求到达</text><text x=\"68\" y=\"102\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">500 QPS</text>\n        <rect x=\"180\" y=\"14\" width=\"200\" height=\"48\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"280\" y=\"34\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">短请求池</text><text x=\"280\" y=\"52\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">认证·配额·路由（几十 ms）</text>\n        <rect x=\"180\" y=\"70\" width=\"200\" height=\"48\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"280\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">AI 调用池</text><text x=\"280\" y=\"108\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">等厂商响应（几秒~几十秒）</text>\n        <rect x=\"180\" y=\"126\" width=\"200\" height=\"48\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"280\" y=\"146\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">后台慢活池</text><text x=\"280\" y=\"164\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">用量事件·缓存更新</text>\n        <rect x=\"430\" y=\"70\" width=\"322\" height=\"48\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"591\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">AI 池堵了 → 只影响 AI 调用</text><text x=\"591\" y=\"108\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">短请求池照常放行，服务不整体卡死</text>\n        <line x1=\"128\" y1=\"80\" x2=\"178\" y2=\"38\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj2)\"/>\n        <line x1=\"128\" y1=\"88\" x2=\"178\" y2=\"94\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj2)\"/>\n        <line x1=\"128\" y1=\"96\" x2=\"178\" y2=\"150\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj2)\"/>\n        <line x1=\"380\" y1=\"94\" x2=\"428\" y2=\"94\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj2)\"/>\n      </svg>\n      <figcaption>图 2 · 不同活配不同班组：一个池堵了不拖垮其他池，每个池可独立监控、独立调参。</figcaption>\n    </figure>\n    <p>池满了怎么办？拒绝策略里推荐 <span class=\"term2\">CallerRunsPolicy</span>：让调用方线程自己执行任务，自然拖慢新请求到达速度，比直接报错更优雅。还有一个隐蔽坑：<code>@Async</code> 默认用 <code>SimpleAsyncTaskExecutor</code>，<b>没有线程池、每个任务新建线程</b>，必须自定义。</p>\n    <h3>虚拟线程：临时工再多，灶台还是两个</h3>\n    <p>JDK 21 的<span class=\"term\">虚拟线程</span>由 JVM 调度，栈按需增长，创建切换成本低，适合<b>大量阻塞式 IO 等待</b>（比如等模型厂商响应）。Spring Boot 3.2+ 一行配置开启：</p>\n    <pre><span class=\"cm\"># application.yml</span>\nspring:\n  threads:\n    virtual:\n      enabled: <span class=\"num\">true</span>\n<span class=\"cm\">// 或为阻塞任务声明执行器（返回 ExecutorService，不是 ThreadFactory）</span>\nExecutors.newVirtualThreadPerTaskExecutor();</pre>\n    <table>\n      <tr><th></th><th>平台线程</th><th>虚拟线程</th></tr>\n      <tr><td>调度</td><td>与 OS 线程一一绑定</td><td>JVM 调度，跑在少量载体线程上</td></tr>\n      <tr><td>栈成本</td><td>每线程约 1MB</td><td>按需增长，初始成本低</td></tr>\n      <tr><td>适合</td><td>CPU 密集、需要池化控制</td><td>大量 IO 等待（SSE、调厂商）</td></tr>\n      <tr><td>不适合</td><td>海量阻塞连接（占栈）</td><td>CPU 密集（频繁切换反而慢）</td></tr>\n    </table>\n    <div class=\"key\"><span class=\"tag\">最常见的误解</span>「用了虚拟线程就能处理更多请求」——错。虚拟线程解决的是<b>「等人」的浪费</b>，解决不了<b>「下游产能」不足</b>。模型 API 响应慢，虚拟线程也要等。所以连接池、信号量/Bulkhead、超时一个都不能少，实际容量必须压测。</div>\n    <div class=\"recap\"><b>收束：</b>按用途隔离线程池；虚拟线程省「等人」的成本，不提升下游容量。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：线程模型、故障诊断</h2>\n    <p>演练一看共享池和隔离池的差别。演练二选一个故障场景，看工具采到的证据、根因和修复——学会「用证据说话」，而不是只说「服务变慢了」。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 线程模型</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e2\"><button data-k=\"api\" class=\"on\">❌ 共享池</button><button data-k=\"cmp\">✅ 隔离池</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e2code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e2log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">一个慢请求，两种结局</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 故障诊断沙盒</b><span class=\"hint\">选故障，看证据→根因→修复</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g2\"><button data-g=\"pile\" class=\"on\">线程堆积</button><button data-g=\"deadlock\">死锁</button><button data-g=\"cpu\">高 CPU</button><button data-g=\"leak\">内存泄漏</button><button data-g=\"ok\">正常</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g2chips\"></div><div class=\"key\" id=\"g2hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>工具证据</span><span>live</span></div><div class=\"logcat-body\" id=\"g2log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">jstack 看线程 · jmap 看堆 · JFR 看火焰图</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>诊断的结论必须由工具证据支持：线程 dump 里谁在 WAITING、堆里谁占最大、火焰图哪段最热。修复后还要有可重复的对比实验。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。拿到一份 GC 日志或线程 dump，你能说出「卡在哪一类资源」了。下一课讲事务、AOP 与安全链路。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>堆 / 栈</td><td>公共操作台 / 点单本</td><td>堆要 GC，栈每线程一个</td></tr>\n      <tr><td>GC / STW</td><td>收台阿姨 / 全店停手</td><td>看暂停时长是否超 P95</td></tr>\n      <tr><td>线程池隔离</td><td>不同活配不同班组</td><td>防慢请求占满所有线程</td></tr>\n      <tr><td>CallerRunsPolicy</td><td>调用方自己干</td><td>过载时自然降速</td></tr>\n      <tr><td>虚拟线程</td><td>随叫随到的临时工</td><td>适合等 IO，不提升下游容量</td></tr>\n      <tr><td>线程 dump</td><td>给服务员拍快照</td><td>jstack 看谁卡着、在等什么</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，并发主线（Spring MVC + JDK 21 虚拟线程 + 阻塞客户端）以课程 README 为准；诊断命令对照 Oracle JDK 21 官方 man 页。演练为模拟证据，非真实采集。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第二篇-JVM并发与线程诊断 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://openjdk.org/jeps/444\" target=\"_blank\" rel=\"noopener\">JEP 444: Virtual Threads</a> <span class=\"src\">— 虚拟线程的设计与适用边界</span></li>\n        <li><a href=\"https://docs.spring.io/spring-boot/reference/features/task-execution-and-scheduling.html\" target=\"_blank\" rel=\"noopener\">Spring Boot · Task Execution and Scheduling</a> <span class=\"src\">— spring.threads.virtual.enabled 与异步执行器</span></li>\n        <li><a href=\"https://docs.oracle.com/en/java/javase/21/garbage-collection/index.html\" target=\"_blank\" rel=\"noopener\">JDK 21 · Garbage Collection Tuning</a> <span class=\"src\">— GC 类型、日志与堆设置</span></li>\n      </ul>\n      <h3>诊断工具</h3>\n      <ul>\n        <li><a href=\"https://docs.oracle.com/en/java/javase/21/docs/specs/man/jstack.html\" target=\"_blank\" rel=\"noopener\">jstack</a> · <a href=\"https://docs.oracle.com/en/java/javase/21/docs/specs/man/jcmd.html\" target=\"_blank\" rel=\"noopener\">jcmd</a> <span class=\"src\">— 线程转储与 JFR 录制</span></li>\n        <li><a href=\"https://eclipse.dev/mat/\" target=\"_blank\" rel=\"noopener\">Eclipse MAT</a> · <a href=\"https://github.com/async-profiler/async-profiler\" target=\"_blank\" rel=\"noopener\">async-profiler</a> <span class=\"src\">— 堆分析与火焰图</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"后厨地图"},{"id":"b","title":"线程模型"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 共享池：一个慢 AI 调用占满，全服务排队\\nExecutorService POOL = Executors.newFixedThreadPool(10);\\n// 认证、路由、AI 调用全用这一个池\\nPOOL.submit(() -> callModelApi(req)); // 等 30s，占着线程\";\n  var CMP=\"// ✅ 隔离池：按用途分班组\\nExecutorService AUTH = Executors.newFixedThreadPool(4);\\nExecutorService AI   = new ThreadPoolExecutor(10,50,60s,\\n    new LinkedBlockingQueue<>(200),\\n    new ThreadPoolExecutor.CallerRunsPolicy()); // 满了自然降速\\n// AI 池堵了，AUTH 池照常放行\";\n  function show(k){document.getElementById(\"e2code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e2log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"AI 调用变慢 → 所有请求一起卡\":\"AI 池堵 → 只影响 AI 调用\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"无法独立监控、独立调参\":\"每个池独立监控，拒绝策略可控\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e2 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e2 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：故障诊断沙盒\n(function(){\n  var G={\n    pile:{tool:'jstack',sev:'bad',title:'线程堆积',\n      chips:['200 线程 WAITING','AI 池耗尽'],\n      hint:'根因：模型厂商响应慢，线程都在等 IO，池被占满。修复：给下游加超时 + 信号量/Bulkhead + 降级，而不是无限加线程。',\n      log:['<span class=\"api\">$ jstack &lt;pid&gt; &gt; thread_dump.txt</span>','<span class=\"warn\">\"exec-1\" WAITING (parking)</span>','<span class=\"c\">  at AIModelService.callModel(:42)</span>','<span class=\"warn\">… 共 200 个线程都在 callModel 等待</span>','<span class=\"ok\">修复：超时 30s→3s + Bulkhead 限并发 + 降级</span>']},\n    deadlock:{tool:'jstack',sev:'bad',title:'死锁',\n      chips:['Found deadlock','互相等锁'],\n      hint:'根因：两个线程互相等待对方持有的锁。jstack 末尾会直接报 \"Found one Java-level deadlock\"。修复：统一加锁顺序，或用带超时的 ReentrantLock.tryLock。',\n      log:['<span class=\"api\">$ jstack &lt;pid&gt;</span>','<span class=\"err\">Found one Java-level deadlock:</span>','<span class=\"warn\">T1 持有 lockA，等待 lockB</span>','<span class=\"warn\">T2 持有 lockB，等待 lockA</span>','<span class=\"ok\">修复：统一锁顺序 / tryLock(timeout)</span>']},\n    cpu:{tool:'top + jstack',sev:'bad',title:'高 CPU',\n      chips:['top -H 定位','RUNNABLE 热栈'],\n      hint:'根因：某线程死循环或频繁 Full GC。步骤：top 找进程 → top -H 找线程 → 线程 ID 转 16 进制 → jstack 找对应栈。也可用 JFR/async-profiler 出 CPU 火焰图。',\n      log:['<span class=\"api\">$ top -H -p &lt;pid&gt;</span>','<span class=\"warn\">线程 12345 CPU 99%</span>','<span class=\"api\">$ printf \"%x\\\\n\" 12345 → 3039</span>','<span class=\"api\">$ jstack &lt;pid&gt; | grep -A10 3039</span>','<span class=\"err\">RUNNABLE 在某循环里 → 定位代码</span>']},\n    leak:{tool:'jmap + MAT',sev:'bad',title:'内存泄漏',\n      chips:['老年代只增不减','Full GC 频繁'],\n      hint:'根因：static 集合只 add 不清理，对象被意外保留引用。jmap 导出堆 → MAT 找 Largest Objects → Path to GC Roots 追引用链。修复：缓存加 TTL 和大小上限。',\n      log:['<span class=\"api\">$ jmap -dump:live,format=b,file=heap.hprof &lt;pid&gt;</span>','<span class=\"warn\">MAT: static CACHE 占 1.8GB</span>','<span class=\"c\">Path to GC Roots: 静态字段强引用</span>','<span class=\"err\">只 add 不 remove → 无法回收</span>','<span class=\"ok\">修复：缓存 TTL + 容量上限 + 定期清理</span>']},\n    ok:{tool:'jstack + GC日志',sev:'on',title:'正常',\n      chips:['Minor GC 几十ms','无 Full GC'],\n      hint:'正常态：Minor GC 每秒几次、暂停几十毫秒，P95 不超标；线程多数 RUNNABLE 或短暂 TIMED_WAITING。这是基线，用来和故障态对比。',\n      log:['<span class=\"ok\">[GC (Allocation Failure) … 0.012 secs]</span>','<span class=\"ok\">Minor GC 暂停 12ms ✓ &lt; 50ms</span>','<span class=\"ok\">线程多数 RUNNABLE / 短暂等待</span>','<span class=\"c\">// 无 Full GC、无 deadlock、堆稳定回落</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g2chips').innerHTML=\n      '<span class=\"chip '+g.sev+'\">'+g.tool+'</span>'+\n      g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g2hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g2log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g2 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g2 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('pile');\n})();\n\nconst QUIZ=[{\"q\":\"1. 堆和栈分别像什么？\",\"opts\":[[\"公共操作台 / 服务员点单本\",true,\"对。堆共享要 GC，栈每线程一个。\"],[\"都是公共的\",false,\"栈是线程私有。\"],[\"都在堆外\",false,\"堆在堆内。\"]]},{\"q\":\"2. 用户「突然卡一下」最该看？\",\"opts\":[[\"GC 日志的 STW 暂停时长\",true,\"对。Full GC 几百 ms 会超时。\"],[\"CPU 温度\",false,\"无关。\"],[\"代码行数\",false,\"无关。\"]]},{\"q\":\"3. 一个池干所有活的后果？\",\"opts\":[[\"一个慢请求占满，全服务排队\",true,\"对。所以要按用途隔离。\"],[\"更快\",false,\"更危险。\"],[\"更省内存\",false,\"无关。\"]]},{\"q\":\"4. 虚拟线程适合什么？\",\"opts\":[[\"大量阻塞式 IO 等待\",true,\"对。等厂商响应时卸载载体线程。\"],[\"CPU 密集计算\",false,\"频繁切换反而慢。\"],[\"提升下游产能\",false,\"下游慢它也得等。\"]]},{\"q\":\"5. @Async 不配线程池会？\",\"opts\":[[\"默认每任务新建线程，无池化\",true,\"对。SimpleAsyncTaskExecutor 没有池。\"],[\"自动用虚拟线程\",false,\"要显式配置。\"],[\"复用主线程\",false,\"不是。\"]]},{\"q\":\"6. 内存泄漏怎么定位？\",\"opts\":[[\"jmap 导出堆 → MAT 找最大对象 → 追 GC Roots 引用链\",true,\"对。用证据找谁保留了引用。\"],[\"只看 top\",false,\"top 看不到对象引用。\"],[\"重启就好\",false,\"治标不治本。\"]]}];" },
    "backend|java|事务·AOP·安全链路": { "body": "<p class=\"lead\">去银行办业务：门口验身份（认证）、柜台确认你能办（授权）、柜员把几件事一次做完要么全成要么全撤（事务）、监控记下谁几点办了什么（审计）。这一课把这条流水线装进代码，并划清：哪些动作绝不能放进事务，身份为什么不能信客户端。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">代理机制</span><span class=\"s\">自调用为何失效</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">事务边界</span><span class=\"s\">短事务+补偿</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">安全三段</span><span class=\"s\">认证·授权·审计</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>代理：那层悄悄替你盖章的前台</h2>\n    <p>初级加个 <code>@Transactional</code> 就生效，很顺手。但遇到「同类里方法调方法，事务突然不生效」「抛了异常却没回滚」就懵了。根源都在同一个机制：<span class=\"term\">Spring 代理</span>。Bean 生命周期走到「初始化后」那步，Spring 用代理对象替换原始对象，事务、AOP、权限都是这一层织入的。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 180\" role=\"img\" aria-label=\"代理洋葱与自调用\">\n        <defs><marker id=\"arj3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"40\" width=\"120\" height=\"56\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"68\" y=\"64\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5B4A2F\">调用方</text><text x=\"68\" y=\"82\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">从外面进来</text>\n        <rect x=\"170\" y=\"20\" width=\"220\" height=\"120\" rx=\"12\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"280\" y=\"44\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">代理对象（前台）</text>\n        <rect x=\"195\" y=\"58\" width=\"170\" height=\"60\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"280\" y=\"82\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">原始对象（柜员）</text><text x=\"280\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">真实业务方法</text>\n        <text x=\"280\" y=\"135\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8A5510\">前置开事务 → 调方法 → 后置提交/回滚</text>\n        <rect x=\"430\" y=\"40\" width=\"322\" height=\"56\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"591\" y=\"62\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#B04A35\">this.inner() 自调用 = 走后门</text><text x=\"591\" y=\"80\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">this 是原始对象，绕过代理 → 事务失效</text>\n        <line x1=\"128\" y1=\"68\" x2=\"168\" y2=\"68\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj3)\"/>\n        <path d=\"M 591 96 Q 591 160 280 160 Q 250 160 250 118\" fill=\"none\" stroke=\"#B04A35\" stroke-width=\"2\" stroke-dasharray=\"4 3\" marker-end=\"url(#arj3)\"/>\n        <text x=\"430\" y=\"172\" font-size=\"10\" fill=\"#B04A35\">自调用直接落到原始对象，没经过前台</text>\n      </svg>\n      <figcaption>图 1 · 走前台（代理）才盖得到章；类内部 this 自调用绕过代理，事务/AOP 悄悄失效。</figcaption>\n    </figure>\n    <p>修复自调用：注入自己的代理 <code>self.inner()</code>，或<b>拆到另一个 Bean</b>（推荐）。Spring Boot 默认 CGLIB 代理（生成子类），有接口时也可 JDK 动态代理。</p>\n    <h3>事务失效排查清单</h3>\n    <table>\n      <tr><th>失效场景</th><th>原因</th><th>修复</th></tr>\n      <tr><td>自调用</td><td>绕过代理</td><td>拆 Bean / 注入 self</td></tr>\n      <tr><td>方法非 public</td><td>代理只拦 public</td><td>改 public</td></tr>\n      <tr><td>异常被 catch 吞掉</td><td>没抛出，触发不了回滚</td><td>重新抛出 / setRollbackOnly</td></tr>\n      <tr><td>抛检查异常</td><td>默认只回滚 RuntimeException</td><td>rollbackFor = Exception.class</td></tr>\n      <tr><td>异步方法</td><td>事务绑线程</td><td>异步内单独开事务</td></tr>\n    </table>\n    <h3>长事务：开着保险箱打电话</h3>\n    <p>最致命的陷阱是把 30 秒的远程模型调用包进事务——数据库连接被占 30 秒，500 QPS 下连接池（假设 50 个）很快耗尽，整服务卡死。<b>核心原则：远程调用绝不进数据库事务。</b>改成「短事务预扣 → 事务外调用 → 失败短事务回补 → 短事务保存」。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 150\" role=\"img\" aria-label=\"短事务加补偿\">\n        <defs><marker id=\"arj3b\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"40\" width=\"150\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"83\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">短事务①预扣</text><text x=\"83\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">毫秒级·还连接</text>\n        <rect x=\"180\" y=\"40\" width=\"180\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"270\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#8A5510\">事务外·调模型</text><text x=\"270\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">30s 不占 DB 连接</text>\n        <rect x=\"382\" y=\"40\" width=\"160\" height=\"52\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"462\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#B04A35\">失败→短事务回补</text><text x=\"462\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">补偿保一致</text>\n        <rect x=\"564\" y=\"40\" width=\"188\" height=\"52\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"658\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">短事务②保存消息</text><text x=\"658\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">毫秒级·还连接</text>\n        <line x1=\"158\" y1=\"66\" x2=\"178\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj3b)\"/>\n        <line x1=\"360\" y1=\"66\" x2=\"380\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj3b)\"/>\n        <line x1=\"542\" y1=\"66\" x2=\"562\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj3b)\"/>\n        <text x=\"380\" y=\"125\" text-anchor=\"middle\" font-size=\"11.5\" fill=\"#A39B8E\">每个事务都短，远程调用不占连接，失败靠补偿——第七/八课深化幂等与异步一致性</text>\n      </svg>\n      <figcaption>图 2 · 预扣 + 补偿：把远程调用挪出事务，连接随用随还。</figcaption>\n    </figure>\n    <p>传播行为最常用的三种：<span class=\"term2\">REQUIRED</span>（默认，跟着当前事务一起办）、<span class=\"term2\">REQUIRES_NEW</span>（另开窗口单独办，审计常用，业务回滚它仍保留）、<span class=\"term2\">NESTED</span>（可局部回滚）。隔离级别里配额扣减用 READ_COMMITTED + 行锁防超扣，一般查询用 MySQL 默认 REPEATABLE_READ，别轻易上 SERIALIZABLE。</p>\n    <div class=\"recap\"><b>收束：</b>事务靠代理生效，自调用会失效；远程调用绝不进事务，用短事务+补偿。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>安全三段式：身份服务端说了算</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 130\" role=\"img\" aria-label=\"安全三段式\">\n        <defs><marker id=\"arj3c\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"34\" width=\"220\" height=\"60\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"118\" y=\"58\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#2F58A8\">认证 Authentication</text><text x=\"118\" y=\"78\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">你是谁·API Key 哈希比对</text>\n        <rect x=\"270\" y=\"34\" width=\"220\" height=\"60\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"380\" y=\"58\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">授权 Authorization</text><text x=\"380\" y=\"78\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">能调哪个模型·RBAC</text>\n        <rect x=\"532\" y=\"34\" width=\"220\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"642\" y=\"58\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">审计 Audit</text><text x=\"642\" y=\"78\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">谁何时做了什么·独立留存</text>\n        <line x1=\"228\" y1=\"64\" x2=\"268\" y2=\"64\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj3c)\"/>\n        <line x1=\"490\" y1=\"64\" x2=\"530\" y2=\"64\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj3c)\"/>\n      </svg>\n      <figcaption>图 3 · 认证查身份、授权查权限、审计记行为，三者职责不混。</figcaption>\n    </figure>\n    <div class=\"key\"><span class=\"tag\">多租户红线</span><b>tenantId 绝不能由客户端传。</b>从请求参数/头直接读 tenantId，等于让客人自报身份证号还不核对——串租户事故几乎都这么来。正确做法：客户端传 API Key，服务端用 Key 的哈希查出对应 tenantId 放进上下文，客户端无法伪造。</div>\n    <ul>\n      <li><b>上下文传递</b>：用 ThreadLocal 存 tenantId/userId/requestId，<b>请求结束必须在 finally 里 clear()</b>，否则线程池复用会读到上个请求的租户，造成越权。虚拟线程场景考虑 JDK 21 的 ScopedValue。</li>\n      <li><b>授权 RBAC</b>：租户→角色→权限→可访问模型。免费版只能调 gpt-3.5，企业版能调 gpt-4/claude。</li>\n      <li><b>接口隔离</b>：调用接口（/v1/chat，API Key）与管理接口（/admin，管理员 JWT + IP 白名单）分开认证。</li>\n      <li><b>审计独立</b>：业务失败审计也要留（REQUIRES_NEW）；合规级审计第八课升级为 Outbox + 重试 + 死信。</li>\n      <li><b>敏感保护</b>：API Key 只存哈希、明文仅创建时返回一次；日志脱敏（手机号 138****5678）；Prompt 默认不记内容；Key 轮换新旧并存平滑过渡。</li>\n    </ul>\n    <div class=\"recap\"><b>收束：</b>身份从认证推导、上下文用完即清、审计独立留存、敏感信息哈希+脱敏。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：事务写法、失效排查</h2>\n    <p>演练一看长事务和短事务+补偿的差别。演练二选一个失效场景，看现象、根因和修复——学会用代理机制解释，而不是试错碰运气。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 事务边界</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e3\"><button data-k=\"api\" class=\"on\">❌ 长事务</button><button data-k=\"cmp\">✅ 短事务+补偿</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e3code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e3log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一个调用，两种命运</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 事务失效排查</b><span class=\"hint\">选场景，看现象→根因→修复</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g3\"><button data-g=\"self\" class=\"on\">自调用</button><button data-g=\"swallow\">吞异常</button><button data-g=\"checked\">检查异常</button><button data-g=\"long\">长事务</button><button data-g=\"ok\">正常</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g3chips\"></div><div class=\"key\" id=\"g3hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>排查证据</span><span>live</span></div><div class=\"logcat-body\" id=\"g3log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">用代理机制解释，不靠猜</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>事务失效都能用「有没有经过代理、异常有没有抛出、连接有没有被长占」三句话解释清楚。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。看到一段 @Transactional 代码，你能立刻判断它会不会失效、会不会拖垮连接池。下一课讲数据库与 Redis 一致性。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>代理 Proxy</td><td>前台代办那一层</td><td>事务/AOP/权限在此织入</td></tr>\n      <tr><td>自调用失效</td><td>走后门自己盖章</td><td>this.xxx() 绕过代理</td></tr>\n      <tr><td>REQUIRED / REQUIRES_NEW</td><td>跟着办 / 另开窗口</td><td>审计用独立事务</td></tr>\n      <tr><td>长事务</td><td>开着保险箱打电话</td><td>远程调用绝不进事务</td></tr>\n      <tr><td>tenantId</td><td>服务端核过的身份牌</td><td>不能信客户端</td></tr>\n      <tr><td>审计</td><td>银行监控录像</td><td>业务回滚也要留</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，事务/AOP 机制对照 Spring Framework 官方文档；多租户与审计口径以课程 README 为准。演练为模拟排查，非真实运行。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第三篇-Spring事务AOP与安全链路 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/annotations.html\" target=\"_blank\" rel=\"noopener\">Spring · @Transactional 与传播/回滚</a> <span class=\"src\">— 事务注解、传播行为、rollbackFor</span></li>\n        <li><a href=\"https://docs.spring.io/spring-framework/reference/core/aop.html\" target=\"_blank\" rel=\"noopener\">Spring · AOP 与代理机制</a> <span class=\"src\">— 切面/通知、JDK 与 CGLIB 代理、自调用限制</span></li>\n        <li><a href=\"https://openjdk.org/jeps/446\" target=\"_blank\" rel=\"noopener\">JEP 446: Scoped Values</a> <span class=\"src\">— 虚拟线程下替代 ThreadLocal 的上下文传递</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"代理与事务边界"},{"id":"b","title":"安全三段式"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 长事务：远程调用占着 DB 连接 30 秒\\n@Transactional\\npublic void chat(ChatRequest req) {\\n    deductQuota(req);            // 快\\n    String r = callModelApi(req); // 30s! 连接一直被占\\n    saveMessage(r);              // 快\\n} // 500 QPS 下连接池耗尽\";\n  var CMP=\"// ✅ 短事务 + 事务外调用 + 补偿\\npublic ChatResponse chat(ChatRequest req) {\\n    deductQuotaTx(req);          // 短事务①预扣\\n    try {\\n        String r = callModelApi(req); // 事务外，不占连接\\n        saveMessageTx(r);        // 短事务②保存\\n        return new ChatResponse(r);\\n    } catch (Exception e) {\\n        refundQuotaTx(req);      // 失败短事务回补\\n        throw e;\\n    }\\n}\";\n  function show(k){document.getElementById(\"e3code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e3log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"连接被占 30s → 池耗尽 → 服务卡死\":\"每个事务毫秒级，连接随用随还\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"失败时配额扣了消息没存，不一致\":\"失败靠补偿回补，保一致\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e3 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e3 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：事务失效排查\n(function(){\n  var G={\n    self:{sev:'bad',title:'自调用失效',chips:['this.inner()','事务没生效'],\n      hint:'根因：this 是原始对象不是代理，绕过了织入事务的前台。修复：拆到另一个 Bean，或注入 self 代理调用。',\n      log:['<span class=\"api\">outer() { this.inner(); }</span>','<span class=\"warn\">inner() 标了 @Transactional 却没开事务</span>','<span class=\"c\">// this 绕过代理</span>','<span class=\"ok\">修复：txService.inner() 跨 Bean 走代理</span>']},\n    swallow:{sev:'bad',title:'吞异常不回滚',chips:['catch 没抛','数据没回滚'],\n      hint:'根因：异常被 catch 吞掉，代理感知不到失败，不会回滚。修复：重新抛出，或 TransactionAspectSupport.setRollbackOnly()。',\n      log:['<span class=\"api\">catch(Exception e){ log.error(...); }</span>','<span class=\"warn\">异常没抛出 → 事务照常提交</span>','<span class=\"err\">配额扣了，脏数据留下</span>','<span class=\"ok\">修复：throw new ChatException(e) / setRollbackOnly</span>']},\n    checked:{sev:'bad',title:'检查异常不回滚',chips:['throws IOException','默认不回滚'],\n      hint:'根因：@Transactional 默认只对 RuntimeException 回滚，检查异常不回滚。修复：rollbackFor = Exception.class。',\n      log:['<span class=\"api\">@Transactional</span>','<span class=\"warn\">方法抛 IOException（检查异常）</span>','<span class=\"err\">默认不回滚 → 数据不一致</span>','<span class=\"ok\">修复：@Transactional(rollbackFor=Exception.class)</span>']},\n    long:{sev:'bad',title:'长事务拖垮池',chips:['连接占 30s','池耗尽'],\n      hint:'根因：远程调用包在事务里，连接被长时间占用。修复：远程调用移出事务，短事务预扣+补偿。',\n      log:['<span class=\"api\">@Transactional 内含 callModelApi(30s)</span>','<span class=\"warn\">DB 连接被占 30s</span>','<span class=\"err\">500 QPS → 50 连接池耗尽 → 卡死</span>','<span class=\"ok\">修复：短事务预扣 → 事务外调用 → 回补</span>']},\n    ok:{sev:'on',title:'正常',chips:['短事务','异常抛出'],\n      hint:'正常态：事务只包数据库操作、毫秒级；异常正确抛出触发回滚；跨 Bean 调用走代理。这是基线。',\n      log:['<span class=\"ok\">短事务预扣（ms 级）→ 还连接</span>','<span class=\"ok\">事务外调模型，不占连接</span>','<span class=\"ok\">失败抛异常 → 回补事务</span>','<span class=\"c\">// 跨 Bean 走代理，事务生效</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g3chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g3hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g3log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g3 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g3 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('self');\n})();\n\nconst QUIZ=[{\"q\":\"1. this.inner() 自调用为什么事务失效？\",\"opts\":[[\"this 是原始对象，绕过了代理\",true,\"对。事务在代理层织入。\"],[\"inner 不是 public\",false,\"那是另一种失效。\"],[\"数据库不支持\",false,\"无关。\"]]},{\"q\":\"2. 远程模型调用应该放在？\",\"opts\":[[\"数据库事务之外\",true,\"对。避免长事务占连接。\"],[\"事务里一起提交\",false,\"会拖垮连接池。\"],[\"异步线程里开大事务\",false,\"仍占连接。\"]]},{\"q\":\"3. 审计为什么常用 REQUIRES_NEW？\",\"opts\":[[\"独立事务，业务回滚审计仍保留\",true,\"对。另开窗口单独办。\"],[\"性能更好\",false,\"反而多占连接。\"],[\"能防进程崩溃\",false,\"那要靠 Outbox。\"]]},{\"q\":\"4. tenantId 应该怎么来？\",\"opts\":[[\"从 API Key 认证结果推导\",true,\"对。服务端说了算。\"],[\"客户端请求头直接传\",false,\"可伪造越权。\"],[\"路径参数读\",false,\"同样可伪造。\"]]},{\"q\":\"5. ThreadLocal 上下文为什么必须 clear？\",\"opts\":[[\"防线程复用读到上个请求的租户\",true,\"对。否则越权。\"],[\"省内存\",false,\"不是主因。\"],[\"加快响应\",false,\"无关。\"]]},{\"q\":\"6. @Transactional 默认对什么回滚？\",\"opts\":[[\"RuntimeException\",true,\"对。检查异常需 rollbackFor。\"],[\"所有 Exception\",false,\"默认不含检查异常。\"],[\"Error 才回滚\",false,\"不对。\"]]}];" },
    "backend|java|数据库与 Redis": { "body": "<p class=\"lead\">资料室百万份档案：没目录从头翻（全表扫描），有索引卡直奔书架（索引）；但「第 100 万份往后 20 份」还是得数前面 99 万份（深分页）。前台把常用数字抄在便利贴上（Redis），账本刚改、便利贴没撕的那几毫秒报的就是旧数（一致性窗口）。这一课解决：查得快、少翻冤枉页、两份记录对不上以谁为准。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">查得快</span><span class=\"s\">EXPLAIN·索引</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">并发正确</span><span class=\"s\">锁·原子扣减</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">缓存一致</span><span class=\"s\">便利贴vs账本</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>用证据让 SQL 变快</h2>\n    <p>中级不靠猜，靠<span class=\"term\">EXPLAIN</span>让数据库自己说「我打算怎么找」。盯四个字段：<code>type</code>（ALL 全表扫描最差，ref/range 较好，const 最好）、<code>key</code>（NULL 没用索引）、<code>rows</code>（预估扫描行数越少越好）、<code>Extra</code>（Using filesort / Using temporary 是危险信号）。再配慢查询日志（<code>long_query_time=1</code>）抓超阈值的 SQL。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 160\" role=\"img\" aria-label=\"索引与深分页\">\n        <defs><marker id=\"arj4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"30\" width=\"360\" height=\"100\" rx=\"12\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"188\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">联合索引 = 先按姓再按名的通讯录</text>\n        <text x=\"188\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">(tenant_id, session_id, created_at)</text>\n        <text x=\"188\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#1E7268\">✅ 从最左列开始给条件才用得上</text>\n        <text x=\"188\" y=\"116\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#B04A35\">❌ 只给 session_id 跳过 tenant_id → 用不上</text>\n        <rect x=\"392\" y=\"30\" width=\"360\" height=\"100\" rx=\"12\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"572\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">深分页 = 数完前 99 万份再拿 20 份</text>\n        <text x=\"572\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">LIMIT 200000, 20 → 扫描丢弃 20 万行</text>\n        <text x=\"572\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#1E7268\">✅ 游标：WHERE created_at &lt; 上页末值 LIMIT 20</text>\n        <text x=\"572\" y=\"116\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">每次只扫 20 行，翻多深都一样快</text>\n      </svg>\n      <figcaption>图 1 · 索引最左前缀匹配查询模式（含排序列避免 filesort）；游标分页替代深分页。</figcaption>\n    </figure>\n    <p>连接池（HikariCP）不是越大越好：经验公式 <code>核心数×2 + 磁盘数</code>，4 核约 10～20；配合第三课短事务，连接用完快还。千万级数据要归档：冷热分离、按时间分区、定期清理。</p>\n    <h3>并发更新：悲观锁 vs 乐观锁</h3>\n    <table>\n      <tr><th>方式</th><th>实现</th><th>适用</th><th>网关场景</th></tr>\n      <tr><td>悲观锁</td><td>SELECT … FOR UPDATE</td><td>冲突频繁</td><td>热点租户配额</td></tr>\n      <tr><td>乐观锁</td><td>version 字段，影响行数=0 重试</td><td>冲突较少</td><td>模型配置更新</td></tr>\n    </table>\n    <p>死锁是两事务反向加锁互相等（A 锁 1 等 2，B 锁 2 等 1）。用 <code>SHOW ENGINE INNODB STATUS</code> 看 LATEST DETECTED DEADLOCK 定位；最有效的治理是<b>统一加锁顺序</b>（都按 id 从小到大），再配短事务与死锁重试。</p>\n    <div class=\"recap\"><b>收束：</b>EXPLAIN 找证据、索引匹配查询、游标治深分页、统一锁序治死锁。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>便利贴与总账：缓存与配额一致性</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 150\" role=\"img\" aria-label=\"Cache-Aside 读写\">\n        <defs><marker id=\"arj4b\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"30\" width=\"360\" height=\"90\" rx=\"12\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"188\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">读：先看便利贴</text>\n        <text x=\"188\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">命中→返回；未命中→查账本→写便利贴(TTL)</text>\n        <text x=\"188\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">Redis 便利贴 · MySQL 总账本</text>\n        <rect x=\"392\" y=\"30\" width=\"360\" height=\"90\" rx=\"12\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"572\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#8A5510\">写：先改账本，再撕便利贴</text>\n        <text x=\"572\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">更新 DB → 删除缓存（不是更新缓存）</text>\n        <text x=\"572\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#B04A35\">下次读重新加载，避免并发写顺序错乱</text>\n      </svg>\n      <figcaption>图 2 · Cache-Aside：写时删缓存而非更新，下次读自然拿到新值。</figcaption>\n    </figure>\n    <p>Cache-Aside 有个消不掉的一致性窗口：A 读未命中拿到旧值 V1，B 更新 V2 并删缓存，A 又把 V1 写回缓存。缓解：短 TTL（配置 10 分钟可接受）、延迟双删、<b>强一致数据干脆不用旁路缓存</b>。关键认知是说清「这个窗口可否接受」：模型配置可接受、权限要缩短 TTL、配额余额不能不一致。</p>\n    <table>\n      <tr><th>缓存问题</th><th>现象</th><th>解决</th></tr>\n      <tr><td>穿透</td><td>查不存在的 key，每次打 DB</td><td>缓存空值 + 布隆过滤器</td></tr>\n      <tr><td>击穿</td><td>热点 key 过期瞬间洪峰</td><td>互斥锁重建 + 逻辑过期</td></tr>\n      <tr><td>雪崩</td><td>大量 key 同时过期</td><td>TTL 加随机 + 多级缓存</td></tr>\n    </table>\n    <div class=\"key\"><span class=\"tag\">tenant_id 贯穿一切</span>共享表多租户模式下，<b>每个查询、索引、唯一约束都必须带 tenant_id</b>（唯一约束需要租户内唯一而非全局唯一）。用 MyBatis-Plus 租户拦截器从框架层自动补条件，防漏写；并用「租户 A 查不到租户 B」的测试验证。</div>\n    <h3>配额：Redis 原子扣减，DB 流水才是真相</h3>\n    <p>配额扣减高频，用 Redis 单线程原子操作避免行锁阻塞。<b>检查+扣减+初始化必须在同一个 Lua 脚本里</b>原子完成——别在 Java 里「发现不存在→读 DB→SET→重试」，并发会用旧快照覆盖已发生的扣减。Key 形如 <code>quota:daily:{tenantId}:{yyyyMMdd}</code>，TTL 到当天结束。</p>\n    <div class=\"note\"><span class=\"tag\">真相源边界</span>Redis 是<b>可重建的实时投影</b>（低延迟准入/预占），数据库不可变用量流水才是<b>账务真相</b>。预占 RESERVED → 结算 SETTLED / 退款 REFUNDED，经 Outbox 可靠落流水；Redis 故障后按对账水位重放流水重建，不能用滞后的 daily_used 直接覆盖。付费配额默认 Fail-Closed。本课管「存哪、怎么一致」，第六课管「计量与限流算法」。</div>\n    <div class=\"recap\"><b>收束：</b>写先改账再撕贴；配额 Lua 原子扣；Redis 是投影、DB 流水是真相。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：原子扣减、慢SQL诊断</h2>\n    <p>演练一看「先读后写」和 Lua 原子扣减的差别。演练二选一个数据层故障，看 EXPLAIN/日志证据、根因和修复。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 配额扣减</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e4\"><button data-k=\"api\" class=\"on\">❌ 先读后写</button><button data-k=\"cmp\">✅ Lua 原子</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e4code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e4log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">100 并发扣 100 次，余额该正好为 0</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 数据层诊断</b><span class=\"hint\">选场景，看证据→根因→修复</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g4\"><button data-g=\"scan\" class=\"on\">全表扫描</button><button data-g=\"page\">深分页</button><button data-g=\"pen\">缓存穿透</button><button data-g=\"dead\">死锁</button><button data-g=\"ok\">正常</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g4chips\"></div><div class=\"key\" id=\"g4hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>诊断证据</span><span>live</span></div><div class=\"logcat-body\" id=\"g4log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">EXPLAIN / 慢日志 / INNODB STATUS</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>慢在哪一步、该加什么索引、改完用什么证据证明变快——三句话讲清，就是中级数据层能力。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。拿一条慢 SQL，你能说清慢在哪、加什么索引、用什么证据证明变快。下一课讲统一接入与多模型路由。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>EXPLAIN</td><td>让数据库说怎么找</td><td>看 type/rows，别猜</td></tr>\n      <tr><td>联合索引</td><td>先姓后名通讯录</td><td>最左前缀</td></tr>\n      <tr><td>游标分页</td><td>记住上次翻到哪</td><td>替代深分页</td></tr>\n      <tr><td>乐观锁</td><td>提交看谁抢先改</td><td>version + 重试</td></tr>\n      <tr><td>一致性窗口</td><td>便利贴没撕那几毫秒</td><td>短 TTL/双删/不用缓存</td></tr>\n      <tr><td>tenant_id</td><td>档案归属标签</td><td>查询/索引/唯一约束都带</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，SQL/锁/缓存机制对照 MySQL 与 Redis 官方文档；配额真相源与 Fail-Closed 口径以课程 README 为准。演练为模拟诊断。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第四篇-数据库Redis与数据一致性 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://dev.mysql.com/doc/refman/8.0/en/explain-output.html\" target=\"_blank\" rel=\"noopener\">MySQL · EXPLAIN 输出解读</a> <span class=\"src\">— type/key/rows/Extra 字段</span></li>\n        <li><a href=\"https://dev.mysql.com/doc/refman/8.0/en/innodb-deadlocks.html\" target=\"_blank\" rel=\"noopener\">MySQL · InnoDB 死锁</a> <span class=\"src\">— 死锁成因与统一加锁顺序</span></li>\n        <li><a href=\"https://redis.io/docs/latest/commands/eval/\" target=\"_blank\" rel=\"noopener\">Redis · EVAL / Lua 脚本</a> <span class=\"src\">— 原子检查+扣减+初始化</span></li>\n        <li><a href=\"https://github.com/brettwooldridge/HikariCP\" target=\"_blank\" rel=\"noopener\">HikariCP</a> <span class=\"src\">— 连接池配置与大小公式</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"查得快"},{"id":"b","title":"缓存与配额一致性"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 先读后写：并发下超扣\\nlong remain = redis.get(key);   // 读到 1\\nif (remain >= 1) {\\n    redis.decrBy(key, 1);        // 100 个请求都读到 1\\n}                                // 都扣 → 余额变 -99\";\n  var CMP=\"-- ✅ Lua：检查+扣减+初始化原子完成\\nlocal r = tonumber(redis.call('GET', KEYS[1]))\\nif r == nil then\\n  redis.call('SET', KEYS[1], ARGV[2], 'EX', ARGV[3], 'NX')\\n  r = tonumber(redis.call('GET', KEYS[1]))\\nend\\nif r < tonumber(ARGV[1]) then return 0 end\\nredis.call('DECRBY', KEYS[1], ARGV[1])\\nreturn 1  -- 单线程原子，不超扣\";\n  function show(k){document.getElementById(\"e4code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e4log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"100 并发 → 余额 -99，超扣\":\"100 并发 → 余额正好 0\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"读和写之间有并发窗口\":\"检查+扣减在同一脚本，原子\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e4 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e4 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：数据层诊断\n(function(){\n  var G={\n    scan:{sev:'bad',title:'全表扫描',chips:['type=ALL','rows=1千万'],\n      hint:'根因：查询没走索引。修复：按查询模式建联合索引 (tenant_id, session_id, created_at)，把排序列也放进去避免 filesort。',\n      log:['<span class=\"api\">EXPLAIN SELECT … WHERE tenant_id=? …</span>','<span class=\"warn\">type=ALL, key=NULL, rows=10000000</span>','<span class=\"err\">Extra=Using filesort · 耗时 3.2s</span>','<span class=\"ok\">加索引后 type=ref, rows=20 · 8ms</span>']},\n    page:{sev:'bad',title:'深分页',chips:['LIMIT 200000,20','越翻越慢'],\n      hint:'根因：offset 要扫描并丢弃前 20 万行。修复：游标分页 WHERE created_at < 上页末值 LIMIT 20，每次只扫 20 行。',\n      log:['<span class=\"api\">LIMIT 200000, 20</span>','<span class=\"warn\">扫描丢弃前 200000 行</span>','<span class=\"err\">翻到第 10000 页极慢</span>','<span class=\"ok\">游标分页：翻多深都稳定 20 行</span>']},\n    pen:{sev:'bad',title:'缓存穿透',chips:['查不存在key','每次打DB'],\n      hint:'根因：恶意查不存在的 key，缓存永远不命中。修复：缓存空值（短 TTL）+ 布隆过滤器拦截。',\n      log:['<span class=\"api\">GET config:不存在的租户</span>','<span class=\"warn\">缓存 miss → 查 DB → 也无</span>','<span class=\"err\">每次都打到 DB</span>','<span class=\"ok\">缓存空值占位 + 布隆过滤器</span>']},\n    dead:{sev:'bad',title:'死锁',chips:['反向加锁','互相等待'],\n      hint:'根因：A 锁 1 等 2，B 锁 2 等 1。修复：统一加锁顺序（按 id 升序）+ 短事务 + 死锁重试。',\n      log:['<span class=\"api\">SHOW ENGINE INNODB STATUS</span>','<span class=\"warn\">LATEST DETECTED DEADLOCK</span>','<span class=\"err\">A 持 1 等 2 / B 持 2 等 1</span>','<span class=\"ok\">统一按 id 升序加锁 → 不再死锁</span>']},\n    ok:{sev:'on',title:'正常',chips:['type=ref','游标分页'],\n      hint:'正常态：查询走索引 rows 小、游标分页稳定、缓存命中率高、无死锁。这是基线。',\n      log:['<span class=\"ok\">type=ref, rows=20, 无 filesort</span>','<span class=\"ok\">游标分页恒定 20 行</span>','<span class=\"ok\">缓存命中 · DB 压力低</span>','<span class=\"c\">// 统一锁序，无死锁</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g4chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g4hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g4log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g4 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g4 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('scan');\n})();\n\nconst QUIZ=[{\"q\":\"1. EXPLAIN 里 type=ALL 意味着？\",\"opts\":[[\"全表扫描，需要加索引\",true,\"对。最差访问类型。\"],[\"走了索引\",false,\"那是 ref/range。\"],[\"用了临时表\",false,\"那是 Extra。\"]]},{\"q\":\"2. 联合索引 (a,b,c) 哪个查询用得上？\",\"opts\":[[\"WHERE a=? AND b=?\",true,\"对。最左前缀。\"],[\"WHERE b=?\",false,\"跳过最左 a。\"],[\"WHERE c=?\",false,\"跳过前面。\"]]},{\"q\":\"3. 深分页怎么治？\",\"opts\":[[\"游标分页：用上页末值做条件\",true,\"对。每次只扫一页。\"],[\"加大 LIMIT\",false,\"更慢。\"],[\"加内存\",false,\"治标不治本。\"]]},{\"q\":\"4. Cache-Aside 写时为什么删缓存而非更新？\",\"opts\":[[\"避免并发写顺序错乱，下次读自然拿新值\",true,\"对。更简单不易错。\"],[\"更新更快\",false,\"不是主因。\"],[\"删除省空间\",false,\"无关。\"]]},{\"q\":\"5. 配额扣减为什么用 Lua 脚本？\",\"opts\":[[\"检查+扣减+初始化原子完成，防超扣\",true,\"对。单线程原子。\"],[\"Lua 更快\",false,\"关键是原子。\"],[\"方便调试\",false,\"无关。\"]]},{\"q\":\"6. 配额账务的真相源是？\",\"opts\":[[\"数据库不可变用量流水\",true,\"对。Redis 只是可重建投影。\"],[\"Redis 余额\",false,\"那是实时投影。\"],[\"客户端上报\",false,\"不可信。\"]]}];" },
    "backend|java|统一接入与路由": { "body": "<p class=\"lead\">原来只接一家厂商，代码写死它的 SDK；客户要求接三家，每家入参、字段、报错全不一样，业务里堆满 if (vendor==…)。中级做法：中间加一排「转换插头」（适配器），业务只认一种统一插座；再加一位前台（路由），先查权限、再看厂商是否营业、最后按成本权重分派。加一家厂商，只是多买一个插头。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">统一协议</span><span class=\"s\">一张报销单</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">适配器</span><span class=\"s\">加厂商零改动</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">路由</span><span class=\"s\">权限·健康·权重</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>统一协议 + 适配器：把厂商差异关进一层</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 160\" role=\"img\" aria-label=\"统一插座与转换插头\">\n        <defs><marker id=\"arj5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"50\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"83\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">业务代码</text><text x=\"83\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">只认统一插座</text>\n        <rect x=\"200\" y=\"50\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"280\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">统一协议</text><text x=\"280\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">Request/Response/Error</text>\n        <rect x=\"402\" y=\"14\" width=\"160\" height=\"40\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"482\" y=\"39\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1E7268\">OpenAI 插头</text>\n        <rect x=\"402\" y=\"60\" width=\"160\" height=\"40\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"482\" y=\"85\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1E7268\">Qwen 插头</text>\n        <rect x=\"402\" y=\"106\" width=\"160\" height=\"40\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"482\" y=\"131\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1E7268\">Claude 插头</text>\n        <rect x=\"604\" y=\"50\" width=\"148\" height=\"56\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"678\" y=\"74\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#5B4A2F\">各厂商 API</text><text x=\"678\" y=\"92\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">方言各异</text>\n        <line x1=\"158\" y1=\"78\" x2=\"198\" y2=\"78\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n        <line x1=\"360\" y1=\"70\" x2=\"400\" y2=\"34\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n        <line x1=\"360\" y1=\"78\" x2=\"400\" y2=\"80\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n        <line x1=\"360\" y1=\"86\" x2=\"400\" y2=\"126\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n        <line x1=\"562\" y1=\"34\" x2=\"602\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n        <line x1=\"562\" y1=\"80\" x2=\"602\" y2=\"78\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n        <line x1=\"562\" y1=\"126\" x2=\"602\" y2=\"90\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5)\"/>\n      </svg>\n      <figcaption>图 1 · 业务只认统一协议，适配器把各家方言翻成普通话；加厂商只新增一个插头类。</figcaption>\n    </figure>\n    <p>统一协议三件套：<span class=\"term2\">GatewayRequest</span>（model 用<b>逻辑名</b>如 chat-standard，不绑厂商；extra 容纳特有参数）、<span class=\"term2\">GatewayResponse</span>（含 usage：promptTokens/completionTokens/totalTokens，<b>计量靠它，绝不能丢</b>）、<span class=\"term2\">GatewayError</span>（统一 code + retryable 标记）。</p>\n    <table>\n      <tr><th>统一错误码</th><th>HTTP</th><th>可重试</th></tr>\n      <tr><td>INVALID_REQUEST / UNAUTHORIZED / FORBIDDEN</td><td>400 / 401 / 403</td><td>否</td></tr>\n      <tr><td>QUOTA_EXCEEDED</td><td>429</td><td>否</td></tr>\n      <tr><td>RATE_LIMITED</td><td>429</td><td>是（退避后）</td></tr>\n      <tr><td>PROVIDER_ERROR / PROVIDER_TIMEOUT</td><td>502 / 504</td><td>是</td></tr>\n    </table>\n    <p>适配器统一接口 <code>ModelProvider</code>：getProviderName / supports / call / stream(逐块消费) / isHealthy。加新厂商只需新建一个 <code>@Component</code> 实现类 + 路由配置加规则，<b>核心路由与业务代码一行不改</b>。课程主线用 Spring MVC + 虚拟线程阻塞读取、StreamingResponseBody 逐块转发；WebFlux 是扩展路线（须用 Reactor Context 传上下文）。</p>\n    <div class=\"note\"><span class=\"tag\">边界口径</span>课程主线在<b>模块化单体</b>内实现这套网关职责（统一协议/适配器/路由作为模块）；独立部署成第二个服务是高级阶段的演进选项，不在中级预设。</div>\n    <div class=\"recap\"><b>收束：</b>统一协议屏蔽差异，适配器加厂商零改动，usage 与 retryable 是关键信息。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>路由分派与流式代理</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 130\" role=\"img\" aria-label=\"路由五步\">\n        <defs><marker id=\"arj5b\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"34\" width=\"130\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"73\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#2F58A8\">① 校验权限</text><text x=\"73\" y=\"76\" text-anchor=\"middle\" font-size=\"10\" fill=\"#B04A35\">无权→403</text>\n        <rect x=\"156\" y=\"34\" width=\"130\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"221\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">② 找支持厂商</text><text x=\"221\" y=\"76\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">supports(model)</text>\n        <rect x=\"304\" y=\"34\" width=\"130\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"369\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#8A5510\">③ 过滤不健康</text><text x=\"369\" y=\"76\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">isHealthy</text>\n        <rect x=\"452\" y=\"34\" width=\"130\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"517\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">④ 权重排序</text><text x=\"517\" y=\"76\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">成本/延迟</text>\n        <rect x=\"600\" y=\"34\" width=\"152\" height=\"56\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"676\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#5B4A2F\">⑤ 记录决策</text><text x=\"676\" y=\"76\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">可追踪</text>\n        <line x1=\"138\" y1=\"62\" x2=\"154\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5b)\"/>\n        <line x1=\"286\" y1=\"62\" x2=\"302\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5b)\"/>\n        <line x1=\"434\" y1=\"62\" x2=\"450\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5b)\"/>\n        <line x1=\"582\" y1=\"62\" x2=\"598\" y2=\"62\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj5b)\"/>\n      </svg>\n      <figcaption>图 2 · 路由五步：权限→候选→健康→权重→留痕。权限必须服务端强制，不能靠前端隐藏入口。</figcaption>\n    </figure>\n    <p>路由规则配置化（weight 流量权重 / priority 备选优先级 / allowed-plans 套餐白名单），可动态调整。普通请求代理：route → call（<b>事务外</b>，呼应 J3）→ record usage；超时分层（连接 3s / 读取 30s / 整体），超时抛 PROVIDER_TIMEOUT（retryable）交 J7 处理。</p>\n    <h3>SSE 流式：边做边端，别堆在手里</h3>\n    <ul>\n      <li><b>逐块透传</b>：用户 ← 业务 ← 网关 ← 厂商，边收边转，<b>不能把完整响应缓冲到内存</b>（首字延迟和内存都完蛋）。</li>\n      <li><b>usage 在流末</b>：流式用量通常最后一块才返回，结束时提取；厂商不返回则按 token 估算（J6）。</li>\n      <li><b>客户端中断</b>：用户关页面 → 捕获断开 → 关闭上游流取消请求释放连接 → 以 reservationId 幂等结算已消耗 token → finally 清 ThreadLocal。不处理就泄漏连接还在计费。</li>\n      <li><b>流式超时不一刀切</b>：首字节超时（10s）+ 空闲超时（15s），<b>不设整体超时</b>（长对话几分钟正常）。</li>\n    </ul>\n    <div class=\"recap\"><b>收束：</b>路由先权限后健康再权重；SSE 边收边转、流末取 usage、中断释放上游。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：调用写法、路由决策</h2>\n    <p>演练一看 if-else 硬编码和适配器的差别。演练二选一个路由场景，看分派结果与原因。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 接入写法</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e5\"><button data-k=\"api\" class=\"on\">❌ if 硬编码</button><button data-k=\"cmp\">✅ 适配器</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e5code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e5log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">加一家厂商，要动几行？</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 路由决策沙盒</b><span class=\"hint\">选场景，看分派结果</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g5\"><button data-g=\"normal\" class=\"on\">正常按权重</button><button data-g=\"forbid\">免费调高级</button><button data-g=\"failover\">openai 故障</button><button data-g=\"allfail\">全故障</button><button data-g=\"cancel\">客户端中断</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g5chips\"></div><div class=\"key\" id=\"g5hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>路由日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g5log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">chat-standard: openai 70% / qwen 30%（备选）</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>新增厂商要动哪几个文件、哪几行绝对不用改——讲得清，就是适配器模式落地了。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。新增一家厂商，你能说清动哪几个文件、哪些代码不用改。下一课讲计量、配额与限流。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>统一协议</td><td>通用报销单</td><td>业务只依赖它</td></tr>\n      <tr><td>适配器</td><td>转换插头</td><td>加厂商零改核心</td></tr>\n      <tr><td>路由</td><td>前台分派表</td><td>权限→健康→权重</td></tr>\n      <tr><td>usage</td><td>用了多少 token</td><td>流末提取，不能丢</td></tr>\n      <tr><td>SSE 代理</td><td>边做边端</td><td>逐块转发+中断释放</td></tr>\n      <tr><td>retryable</td><td>这错能不能重试</td><td>429限流/502/504 可重试</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，MVC 流式主线与模块化单体口径以课程 README 为准；SSE 与适配器机制对照官方规范。演练为模拟路由。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第五篇-AI网关一统一接入与路由 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档与规范</h3>\n      <ul>\n        <li><a href=\"https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-ann-async.html\" target=\"_blank\" rel=\"noopener\">Spring MVC · 异步与 StreamingResponseBody</a> <span class=\"src\">— 流式逐块转发</span></li>\n        <li><a href=\"https://html.spec.whatwg.org/multipage/server-sent-events.html\" target=\"_blank\" rel=\"noopener\">HTML 规范 · Server-Sent Events</a> <span class=\"src\">— SSE 流式协议</span></li>\n        <li><a href=\"https://refactoring.guru/design-patterns/adapter\" target=\"_blank\" rel=\"noopener\">适配器模式 · Refactoring Guru</a> <span class=\"src\">— 统一接口屏蔽差异</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"统一协议与适配器"},{"id":"b","title":"路由与流式代理"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ if 硬编码：换厂商改代码重发布\\nif (vendor.equals(\\\"openai\\\")) {\\n    return openAiSdk.call(req);   // 入参/报错各不同\\n} else if (vendor.equals(\\\"qwen\\\")) {\\n    return qwenSdk.call(req);\\n} // 加一家 → 改这里 + 业务到处改\";\n  var CMP=\"// ✅ 适配器：加厂商只新增一个类\\npublic interface ModelProvider {\\n    GatewayResponse call(GatewayRequest r);\\n    void stream(GatewayRequest r, Consumer<GatewayChunk> c);\\n    boolean isHealthy();\\n}\\n@Component\\nclass QwenProvider implements ModelProvider { … }\\n// 核心路由/业务一行不改\";\n  function show(k){document.getElementById(\"e5code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e5log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"加厂商 → 改核心 + 重新发布\":\"加厂商 → 新增一个 @Component 类\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"业务认识每家厂商\":\"业务只认统一协议\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e5 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e5 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：路由决策沙盒\n(function(){\n  var G={\n    normal:{sev:'on',title:'正常按权重',chips:['openai 70%','qwen 30%'],\n      hint:'两厂商都健康，按权重分派：约 70% 走 openai(gpt-3.5)，30% 走 qwen(qwen-plus)。决策记入日志可追踪。',\n      log:['<span class=\"api\">route(chat-standard, T001)</span>','<span class=\"ok\">权限✓ → 候选[openai,qwen] → 都健康</span>','<span class=\"ok\">按权重选中 openai (70%)</span>','<span class=\"c\">// 记录：model/tenant/selected</span>']},\n    forbid:{sev:'bad',title:'免费调高级',chips:['chat-advanced','403'],\n      hint:'chat-advanced 仅 ENTERPRISE 套餐可用。免费租户请求 → 第①步权限校验直接 403，不进入候选。权限服务端强制。',\n      log:['<span class=\"api\">route(chat-advanced, 免费租户)</span>','<span class=\"err\">① 权限校验失败 → FORBIDDEN 403</span>','<span class=\"c\">// 前端隐藏入口没用，API 直调也拦</span>']},\n    failover:{sev:'on',title:'openai 故障',chips:['过滤不健康','切 qwen'],\n      hint:'openai 当前不健康，第③步过滤掉，候选只剩 qwen → 自动切到 qwen。这就是 priority 备选的价值。',\n      log:['<span class=\"api\">route(chat-standard, T001)</span>','<span class=\"warn\">openai isHealthy=false → 过滤</span>','<span class=\"ok\">候选[qwen] → 选中 qwen</span>','<span class=\"c\">// 故障切换，业务无感</span>']},\n    allfail:{sev:'bad',title:'全故障',chips:['候选为空','PROVIDER_ERROR'],\n      hint:'所有支持厂商都不健康，候选为空 → 抛 PROVIDER_ERROR(502, retryable)。交 J7 重试/降级处理。',\n      log:['<span class=\"api\">route(chat-standard, T001)</span>','<span class=\"err\">候选过滤后为空</span>','<span class=\"err\">PROVIDER_ERROR 502 (retryable=true)</span>','<span class=\"c\">// 交第七课重试/降级</span>']},\n    cancel:{sev:'bad',title:'客户端中断',chips:['关页面','释放上游'],\n      hint:'用户中途关页面：捕获断开 → 关闭上游流取消请求释放连接 → 幂等结算已消耗 token → 清 ThreadLocal。不处理就泄漏+继续计费。',\n      log:['<span class=\"warn\">用户关闭浏览器 → 下游断开</span>','<span class=\"api\">关闭 ProviderStream，取消上游</span>','<span class=\"ok\">settlePartial(reservationId, 已耗 token)</span>','<span class=\"ok\">finally 清 ThreadLocal</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g5chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g5hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g5log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g5 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g5 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('normal');\n})();\n\nconst QUIZ=[{\"q\":\"1. 统一协议里 model 字段应该用？\",\"opts\":[[\"逻辑模型名（如 chat-standard）\",true,\"对。不绑具体厂商。\"],[\"厂商具体模型名\",false,\"那就绑死了。\"],[\"厂商 SDK 类名\",false,\"更不对。\"]]},{\"q\":\"2. 加一家新厂商要改核心路由代码吗？\",\"opts\":[[\"不用，新增一个 Provider 实现类即可\",true,\"对。适配器模式价值。\"],[\"要改路由核心\",false,\"那就没解耦。\"],[\"要改业务代码\",false,\"业务零感知。\"]]},{\"q\":\"3. 路由第一步是？\",\"opts\":[[\"校验租户权限\",true,\"对。无权直接 403。\"],[\"按权重选厂商\",false,\"那是后面。\"],[\"调厂商 API\",false,\"更后。\"]]},{\"q\":\"4. 流式响应的 usage 通常何时拿到？\",\"opts\":[[\"流的最后一块\",true,\"对。结束时提取。\"],[\"第一块\",false,\"通常最后。\"],[\"不需要 usage\",false,\"计量靠它。\"]]},{\"q\":\"5. 客户端中断流式请求要做什么？\",\"opts\":[[\"关闭上游流释放连接+幂等结算已耗token\",true,\"对。否则泄漏+计费。\"],[\"不管它\",false,\"会泄漏。\"],[\"继续收完整流\",false,\"浪费资源。\"]]},{\"q\":\"6. 流式超时怎么设？\",\"opts\":[[\"首字节+空闲超时，不设整体超时\",true,\"对。长对话几分钟正常。\"],[\"整体 30 秒一刀切\",false,\"会切断长对话。\"],[\"不设任何超时\",false,\"慢厂商拖垮。\"]]}];" },
    "backend|java|计量配额限流": { "body": "<p class=\"lead\">AI 调用按 Token 算成本：问句「你好」和贴篇长文差几十倍，不能按次数收费。把它想成自助餐厅：进门交押金（预占），吃完按实际结算，没吃成退押金；门口一桶代币（令牌桶），取一枚放行一人，桶空请稍等，桶以固定速度补货、能攒余量但攒不爆。这一课让扣减不超、不重、可退。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">计量</span><span class=\"s\">Token与成本</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">限流</span><span class=\"s\">RPM·TPM·令牌桶</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">预占结算</span><span class=\"s\">押金状态机</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>计量维度与限流算法</h2>\n    <p>四个计量维度各管一件事：<span class=\"term2\">请求数</span>（防刷/RPM）、<span class=\"term2\">并发数</span>（保护后端）、<span class=\"term2\">Token 数</span>（成本/配额/TPM）、<span class=\"term2\">成本</span>（计费/预算）。Token = 输入 prompt（请求前可算）+ 输出 completion（生成完才知）；成本 = 输入/1000×输入单价 + 输出/1000×输出单价，输入输出单价不同。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 160\" role=\"img\" aria-label=\"固定窗口临界与令牌桶\">\n        <rect x=\"8\" y=\"30\" width=\"360\" height=\"100\" rx=\"12\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"188\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#B04A35\">固定窗口的临界陷阱</text>\n        <text x=\"188\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">限 100/分：10:00:59 刷 100 + 10:01:01 刷 100</text>\n        <text x=\"188\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#B04A35\">2 秒内挨了 200 次，规则却没破</text>\n        <text x=\"188\" y=\"116\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#1E7268\">滑动窗口：回头看最近 60 秒，边界不翻倍</text>\n        <rect x=\"392\" y=\"30\" width=\"360\" height=\"100\" rx=\"12\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"572\" y=\"52\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"bold\" fill=\"#1E7268\">令牌桶：允许突发但有天花板</text>\n        <text x=\"572\" y=\"76\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">固定速率补令牌，桶满丢弃，桶空限流</text>\n        <text x=\"572\" y=\"98\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">容量 100 + 速率 10/s：突发 100 全过</text>\n        <text x=\"572\" y=\"116\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">之后长期 ≤ 10/s</text>\n      </svg>\n      <figcaption>图 1 · 固定窗口有临界双倍流量；滑动窗口更平滑；令牌桶允许突发、上限即桶容量。</figcaption>\n    </figure>\n    <p>AI 网关必须<b>同时限 RPM 和 TPM</b>：光限请求数不够，100 个请求×每个 5 万 token = 500 万 token/分钟，会瞬间打爆厂商 TPM。RPM 桶每请求耗 1 令牌，TPM 桶每请求耗 N（预估 token）个。所有窗口计数、令牌补充与扣减都要在<b>一个 Lua 脚本</b>里原子完成（分两次发 INCR+EXPIRE 可能崩溃留永久 Key）；滑动窗口用 Redis 服务端 TIME 避免多实例时钟不一致。</p>\n    <div class=\"recap\"><b>收束：</b>按 Token 计量；RPM+TPM 双桶；限流算法原子化，令牌桶允许有界突发。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>预占—结算—退款：一条幂等状态机</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 150\" role=\"img\" aria-label=\"预占结算状态机\">\n        <defs><marker id=\"arj6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"50\" width=\"120\" height=\"50\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"68\" y=\"80\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5B4A2F\">CREATED</text>\n        <rect x=\"170\" y=\"50\" width=\"140\" height=\"50\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"240\" y=\"72\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">RESERVED</text><text x=\"240\" y=\"90\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">预占预估最大值</text>\n        <rect x=\"360\" y=\"20\" width=\"150\" height=\"46\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"435\" y=\"48\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">SETTLED 实收</text>\n        <rect x=\"360\" y=\"84\" width=\"150\" height=\"46\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"435\" y=\"112\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">REFUNDED 退款</text>\n        <rect x=\"556\" y=\"50\" width=\"196\" height=\"50\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"654\" y=\"72\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#B04A35\">RECONCILE_REQUIRED</text><text x=\"654\" y=\"90\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">异常→待对账</text>\n        <line x1=\"128\" y1=\"75\" x2=\"168\" y2=\"75\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj6)\"/>\n        <line x1=\"310\" y1=\"66\" x2=\"358\" y2=\"43\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj6)\"/>\n        <line x1=\"310\" y1=\"84\" x2=\"358\" y2=\"107\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj6)\"/>\n        <line x1=\"510\" y1=\"43\" x2=\"554\" y2=\"66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj6)\"/>\n        <line x1=\"510\" y1=\"107\" x2=\"554\" y2=\"84\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj6)\"/>\n      </svg>\n      <figcaption>图 2 · 预占→结算/退款，异常进待对账；同一 reservationId 只能从合法前置状态转换。</figcaption>\n    </figure>\n    <p>流式结束前不知道输出 token，所以<b>先按预估最大值预占</b>（请求开始就锁定配额，100 并发只够 60 个预占，后 40 个直接拒），<b>结束按实际结算多退少补</b>（预占 5000 实际 3000 退 2000）。配额检查必须在调模型<b>之前</b>，否则钱花了才拒。</p>\n    <ul>\n      <li><b>客户端断开</b>：预占 5000、生成到 2000 关页面 → 按 2000 结算、退 3000，为已生成部分付费。</li>\n      <li><b>厂商无 usage</b>：tiktoken 本地估算 / 字符换算（中文约 1.5 字符/token、英文约 4）/ 标记估算值待对账校正。</li>\n      <li><b>重试不重扣</b>：requestId 幂等，唯一约束 tenantId+requestId+operation，SETTLE/REFUND 重复执行不重复扣。</li>\n      <li><b>Redis 故障取舍</b>：限流 Fail-Open（保护短暂失效可接受），付费配额 Fail-Closed（避免超额损失），两者都要告警。</li>\n      <li><b>超限响应</b>：429 带错误码（RATE_LIMITED/QUOTA_EXCEEDED）+ Retry-After + 超限维度。</li>\n    </ul>\n    <div class=\"recap\"><b>收束：</b>先押后结、按真实用量扣、查扣原子一次完成、重试幂等不重扣。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：原子扣减、令牌桶模拟</h2>\n    <p>演练一看先读后写和 Lua 组合原子的差别。演练二拖滑块调桶容量、补令牌速率和突发请求数，看放行多少、限流多少。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 组合检查扣减</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e6\"><button data-k=\"api\" class=\"on\">❌ 先读后写</button><button data-k=\"cmp\">✅ Lua 组合原子</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e6code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e6log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">RPM/TPM/配额要么全过要么全不过</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 令牌桶模拟器</b><span class=\"hint\">拖滑块，看突发放行与限流</span></div>\n      <div class=\"controls\">\n        <div class=\"ctl\"><label>桶容量</label><input type=\"range\" id=\"g6cap\" min=\"10\" max=\"200\" value=\"100\"><span class=\"val\" id=\"g6capV\">100</span></div>\n        <div class=\"ctl\"><label>补令牌/秒</label><input type=\"range\" id=\"g6rate\" min=\"1\" max=\"50\" value=\"10\"><span class=\"val\" id=\"g6rateV\">10</span></div>\n        <div class=\"ctl\"><label>突发请求</label><input type=\"range\" id=\"g6burst\" min=\"10\" max=\"300\" value=\"150\"><span class=\"val\" id=\"g6burstV\">150</span></div>\n      </div>\n      <div class=\"lab-body\"><div><div class=\"stats\" id=\"g6stats\"></div><div class=\"chips\" id=\"g6chips\"></div><div class=\"key\" id=\"g6hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>令牌桶日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g6log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">桶平时攒满，突发一次性消耗，之后受速率限制</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>画出一次请求从预占、调用到结算的完整流转，指出哪一步可能扣重、怎么防——就是中级控制层能力。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你能画出预占→结算的完整状态流转，并指出哪步可能扣重。下一课讲幂等与韧性治理。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>Token</td><td>按字数算的用量</td><td>输入+输出，成本依据</td></tr>\n      <tr><td>RPM / TPM</td><td>每分钟几次/多少Token</td><td>各配一个桶</td></tr>\n      <tr><td>令牌桶</td><td>门口那桶代币</td><td>允许有界突发</td></tr>\n      <tr><td>原子扣减</td><td>查余额扣款一次做完</td><td>Lua 防超扣</td></tr>\n      <tr><td>预占 reservationId</td><td>押金及押金号</td><td>贯穿链路防扣重</td></tr>\n      <tr><td>429</td><td>额度不够稍后再来</td><td>给 Retry-After</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，计量/限流/预占口径以课程 README 为准；与第四课数据层分工（本课控制层）。演练为模拟，非真实压测。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第六篇-AI网关二计量配额与限流 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://redis.io/docs/latest/commands/eval/\" target=\"_blank\" rel=\"noopener\">Redis · EVAL / Lua 原子脚本</a> <span class=\"src\">— 组合检查与扣减原子化</span></li>\n        <li><a href=\"https://redis.io/docs/latest/commands/time/\" target=\"_blank\" rel=\"noopener\">Redis · TIME</a> <span class=\"src\">— 滑动窗口用服务端时钟</span></li>\n        <li><a href=\"https://platform.openai.com/docs/guides/rate-limits\" target=\"_blank\" rel=\"noopener\">OpenAI · Rate Limits（RPM/TPM）</a> <span class=\"src\">— 厂商限流维度参考</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"计量与限流算法"},{"id":"b","title":"预占结算退款"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 先读后写 + 分步检查：超扣/部分成功\\nlong q = redis.get(quotaKey);   // 读 100\\nif (q >= need) redis.decrBy(quotaKey, need);\\n// 并发都读到 100 → 都扣 → 超扣\\n// RPM 过了但配额扣失败 → 中间状态\";\n  var CMP=\"-- ✅ Lua 组合：RPM+TPM+配额一次原子\\nif rpm >= limit then return 'RATE_LIMITED_RPM' end\\nif quota < need then return 'QUOTA_EXCEEDED' end\\n-- 全过才一次性写入\\nredis.call('INCR', rpmKey)\\nredis.call('DECRBY', quotaKey, need)\\nreturn 'OK'  -- 要么全过要么全不过\";\n  function show(k){document.getElementById(\"e6code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e6log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"并发超扣 + 部分成功中间态\":\"原子：全过或全不过，无中间态\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"查和扣之间有窗口\":\"一次网络往返完成所有检查\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e6 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e6 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：令牌桶模拟器\n(function(){\n  function val(id){return parseInt(document.getElementById(id).value,10);}\n  function calc(){\n    var cap=val('g6cap'), rate=val('g6rate'), burst=val('g6burst');\n    document.getElementById('g6capV').textContent=cap;\n    document.getElementById('g6rateV').textContent=rate;\n    document.getElementById('g6burstV').textContent=burst;\n    var pass=Math.min(burst,cap), rej=burst-pass;\n    document.getElementById('g6stats').innerHTML=\n      '<div class=\"stat-box good\"><b>'+pass+'</b><small>突发放行</small></div>'+\n      '<div class=\"stat-box '+(rej>0?'bad':'good')+'\"><b>'+rej+'</b><small>被限流</small></div>'+\n      '<div class=\"stat-box\"><b>'+rate+'/s</b><small>长期速率上限</small></div>';\n    document.getElementById('g6chips').innerHTML=\n      '<span class=\"chip on\">桶容量 '+cap+'</span>'+\n      '<span class=\"chip '+(rej>0?'bad':'on')+'\">'+(rej>0?'突发超出桶容量':'突发全放行')+'</span>';\n    document.getElementById('g6hint').innerHTML='<span class=\"tag\">令牌桶</span>桶平时攒满 '+cap+' 个令牌，突发 '+burst+' 个请求一次性消耗：放行 '+pass+'、限流 '+rej+'。之后每秒最多补 '+rate+' 个，长期速率不超过它。突发有天花板（桶容量），不会无限。';\n    document.getElementById('g6log').innerHTML=[\n      '<div><span class=\"api\">桶初始攒满 = '+cap+' 令牌</span></div>',\n      '<div><span class=\"ok\">突发 '+burst+' 请求 → 放行 min('+burst+','+cap+') = '+pass+'</span></div>',\n      rej>0?'<div><span class=\"warn\">超出 '+rej+' 个 → 429 RATE_LIMITED</span></div>':'<div><span class=\"ok\">无请求被限流</span></div>',\n      '<div><span class=\"c\">// 之后按 '+rate+'/s 补令牌，长期速率 ≤ '+rate+'/s</span></div>'\n    ].join('');\n  }\n  ['g6cap','g6rate','g6burst'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});\n  calc();\n})();\n\nconst QUIZ=[{\"q\":\"1. AI 为什么不能只按请求次数计费？\",\"opts\":[[\"一次请求成本随 Token 差几十倍\",true,\"对。要按 Token 算。\"],[\"次数更准\",false,\"恰恰不准。\"],[\"Token 不重要\",false,\"成本依据。\"]]},{\"q\":\"2. 为什么要同时限 RPM 和 TPM？\",\"opts\":[[\"少数大 Token 请求就能打爆厂商 TPM\",true,\"对。100×5万=500万。\"],[\"RPM 够了\",false,\"不够。\"],[\"TPM 没用\",false,\"必须限。\"]]},{\"q\":\"3. 固定窗口的临界问题是？\",\"opts\":[[\"两个窗口边界处短时双倍流量\",true,\"对。2秒200次。\"],[\"内存太大\",false,\"那是滑动窗口。\"],[\"不能突发\",false,\"那是漏桶。\"]]},{\"q\":\"4. 流式计量怎么防超额？\",\"opts\":[[\"先按预估最大值预占，结束按实际结算\",true,\"对。多退少补。\"],[\"等生成完才扣\",false,\"并发会超。\"],[\"不预占\",false,\"会超额调用。\"]]},{\"q\":\"5. 客户端断开时怎么结算？\",\"opts\":[[\"按已生成 Token 结算，退还多预占的\",true,\"对。为已生成部分付费。\"],[\"全额扣\",false,\"不公平。\"],[\"全额退\",false,\"已生成的该付。\"]]},{\"q\":\"6. 付费配额 Redis 故障倾向？\",\"opts\":[[\"Fail-Closed 拒绝，避免超额损失\",true,\"对。限流可 Fail-Open。\"],[\"Fail-Open 放行\",false,\"付费会超额。\"],[\"不管\",false,\"需要明确取舍。\"]]}];" },
    "backend|java|幂等与韧性": { "body": "<p class=\"lead\">厂商变慢，服务傻等 30 秒，请求越堆越多，线程池占满，连不依赖它的功能也挂了。家里电路早给了答案：一路短路，保险丝只断这一路，别的屋照常亮；过会儿小心试送一次电，能通就恢复——这是熔断三态。敲门要有分寸：越等越久、别同一秒一起敲（退避+抖动）；每次敲门带同一张回执号，否则对方已开门你不知道又敲一次，就重复扣费（幂等）。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">幂等</span><span class=\"s\">回执号防重扣</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">超时预算</span><span class=\"s\">沿链路递减</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">熔断降级</span><span class=\"s\">故障关一路</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>幂等与端到端超时预算</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 150\" role=\"img\" aria-label=\"超时预算沿链路递减\">\n        <defs><marker id=\"arj7\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"40\" width=\"160\" height=\"60\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"88\" y=\"64\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">用户请求</text><text x=\"88\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">总预算 30s</text>\n        <rect x=\"210\" y=\"40\" width=\"160\" height=\"60\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"290\" y=\"64\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">Gateway</text><text x=\"290\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">已过 1s，剩 29s</text>\n        <rect x=\"412\" y=\"40\" width=\"160\" height=\"60\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"492\" y=\"64\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">调厂商</text><text x=\"492\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5B4A2F\">预留 2s，给 27s</text>\n        <rect x=\"614\" y=\"40\" width=\"138\" height=\"60\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"683\" y=\"64\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#5B4A2F\">超 27s 放弃</text><text x=\"683\" y=\"84\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#1E7268\">用户最多等 30s</text>\n        <line x1=\"168\" y1=\"70\" x2=\"208\" y2=\"70\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj7)\"/>\n        <line x1=\"370\" y1=\"70\" x2=\"410\" y2=\"70\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj7)\"/>\n        <line x1=\"572\" y1=\"70\" x2=\"612\" y2=\"70\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj7)\"/>\n        <text x=\"380\" y=\"128\" text-anchor=\"middle\" font-size=\"11\" fill=\"#B04A35\">❌ 各层各设 30s → 最坏用户等 90s</text>\n      </svg>\n      <figcaption>图 1 · 总预算沿链路递减，每层花一部分、剩余传下一层；超时还要取消下游、停止计费。</figcaption>\n    </figure>\n    <p><span class=\"term2\">幂等</span>＝同一操作执行一次和多次结果相同（电梯按钮 vs 转账按钮）。<b>铁律：没有幂等，不做自动重试</b>。幂等键由客户端提供（Idempotency-Key），记录表唯一约束 (tenant_id, idempotency_key)，存请求指纹 request_hash：hash 相同→返回已有结果；hash 不同→409 IDEMPOTENCY_KEY_REUSED；PROCESSING 要有租约/超时恢复防崩溃卡住；流式只存状态不塞全量数据。</p>\n    <p><span class=\"term2\">超时预算</span>沿链路递减（图 1），每步检查剩余预算，耗尽抛 PROVIDER_TIMEOUT；超时后<b>取消下游</b>释放连接停止计费，不能只返回错误让厂商继续跑。分层：连接 3s / 首字节 10s / 空闲 15s / 总预算按业务。<b>没有超时，不谈故障隔离。</b></p>\n    <div class=\"recap\"><b>收束：</b>幂等键防重扣是重试前提；超时预算递减并取消下游，是隔离前提。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>重试、熔断、降级与隔离</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 160\" role=\"img\" aria-label=\"熔断三态\">\n        <defs><marker id=\"arj7b\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"40\" y=\"50\" width=\"170\" height=\"60\" rx=\"12\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"125\" y=\"74\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1E7268\">Closed 合闸</text><text x=\"125\" y=\"94\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">正常放行</text>\n        <rect x=\"300\" y=\"50\" width=\"170\" height=\"60\" rx=\"12\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"385\" y=\"74\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#B04A35\">Open 跳闸</text><text x=\"385\" y=\"94\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">快速失败不调用</text>\n        <rect x=\"560\" y=\"50\" width=\"170\" height=\"60\" rx=\"12\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"645\" y=\"74\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#8A5510\">Half-Open 试送</text><text x=\"645\" y=\"94\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">放少量探测</text>\n        <path d=\"M210,66 L298,66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj7b)\"/><text x=\"254\" y=\"58\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#B04A35\">失败率超阈值</text>\n        <path d=\"M470,66 L558,66\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj7b)\"/><text x=\"514\" y=\"58\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8A5510\">冷却时间到</text>\n        <path d=\"M645,110 L645,135 L125,135 L125,112\" stroke=\"#2E9488\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#arj7b)\"/><text x=\"385\" y=\"150\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#1E7268\">探测成功→Closed（失败→回 Open）</text>\n      </svg>\n      <figcaption>图 2 · 熔断三态：合闸正常、跳闸快速失败、半开试送电；探测成功才恢复。</figcaption>\n    </figure>\n    <p><b>重试</b>只重试临时性错误（429 退避后 / 500 / 502/503/504 / 网络失败），不重试确定性错误（400/401/403）；用<b>指数退避 + 随机抖动</b>（1s→2s→4s ± 随机）防重试风暴，限次数（如 3）且预算耗尽即停。</p>\n    <ul>\n      <li><b>按厂商隔离熔断</b>：每厂商一个独立熔断器，A 挂只断 A，B 照常（不全局误伤）。Resilience4j 配失败率 50% / 慢调用率 80% / 冷却 30s / 半开探测 5 个。</li>\n      <li><b>故障切换边界</b>：仅网络/5xx/超时可切；400/401/403/配额/内容安全拒绝<b>不能切</b>；SSE 首 token 前可切、已输出不透明切；每次尝试耗同一总预算。</li>\n      <li><b>降级可解释</b>：备用厂商 → 缓存相似回答 → 友好提示 → 排队；不返回 500 白屏。</li>\n      <li><b>舱壁隔离</b>：每厂商独立线程池/连接池，A 占满不拖垮 B（呼应 J2）。</li>\n      <li><b>故障注入验证</b>：WireMock 注入延迟/500/429/间歇/宕机，验证熔断触发、切换成功、半开自动恢复。</li>\n    </ul>\n    <div class=\"note\"><span class=\"tag\">韧性四原则</span>没有幂等不重试；没有超时不谈隔离；没有指标不自动切换；没有恢复验证不算完成降级。</div>\n    <div class=\"recap\"><b>收束：</b>退避抖动防风暴，熔断按厂商隔离，降级可解释，恢复要验证。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：重试写法、熔断状态机</h2>\n    <p>演练一看盲目重试和「幂等+退避抖动」的差别。演练二点状态按钮，走一遍熔断的合闸→跳闸→试送→恢复。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 重试策略</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e7\"><button data-k=\"api\" class=\"on\">❌ 盲目立即重试</button><button data-k=\"cmp\">✅ 幂等+退避抖动</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e7code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e7log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">重试前问：幂等吗？预算够吗？</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 熔断状态机沙盒</b><span class=\"hint\">点状态，看转换与行为</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g7\"><button data-g=\"closed\" class=\"on\">Closed</button><button data-g=\"open\">失败率超→Open</button><button data-g=\"half\">冷却→Half-Open</button><button data-g=\"recover\">探测成功→Closed</button><button data-g=\"isolate\">按厂商隔离</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g7chips\"></div><div class=\"key\" id=\"g7hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>熔断日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g7log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">阈值：失败率 50% / 慢调用 80% / 冷却 30s</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>设计一次重试前，先回答「这操作幂等吗」「总预算还剩多少」「失败会不会拖垮别的模块」——答得出就是韧性思维。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你能在重试前回答幂等、预算、隔离三问。下一课讲消息队列与异步一致性。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>幂等键</td><td>已办过的回执号</td><td>重试不重扣的前提</td></tr>\n      <tr><td>超时预算</td><td>这趟总共能花多久</td><td>沿链路递减+取消下游</td></tr>\n      <tr><td>退避/抖动</td><td>越等越久还错峰</td><td>防重试风暴</td></tr>\n      <tr><td>熔断三态</td><td>合闸/跳闸/试送电</td><td>按厂商隔离</td></tr>\n      <tr><td>降级/切换</td><td>不通就换备用</td><td>对用户可解释</td></tr>\n      <tr><td>故障注入</td><td>主动弄挂一次</td><td>验证恢复能力</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，韧性口径以课程 README 为准；熔断/隔离参数对照 Resilience4j 文档。演练为模拟状态机，非真实故障注入。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第七篇-AI网关三幂等与韧性治理 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://resilience4j.readme.io/docs/circuitbreaker\" target=\"_blank\" rel=\"noopener\">Resilience4j · CircuitBreaker</a> <span class=\"src\">— 熔断三态与阈值配置</span></li>\n        <li><a href=\"https://resilience4j.readme.io/docs/bulkhead\" target=\"_blank\" rel=\"noopener\">Resilience4j · Bulkhead</a> <span class=\"src\">— 舱壁资源隔离</span></li>\n        <li><a href=\"https://wiremock.org/docs/\" target=\"_blank\" rel=\"noopener\">WireMock · 文档</a> <span class=\"src\">— 故障注入与恢复验证</span></li>\n        <li><a href=\"https://datatracker.ietf.org/doc/draft-ietf-httpapi-idempotency-key-header/\" target=\"_blank\" rel=\"noopener\">IETF · Idempotency-Key 头草案</a> <span class=\"src\">— 幂等键约定参考</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"幂等与超时预算"},{"id":"b","title":"重试熔断降级隔离"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 盲目立即重试：重扣 + 重试风暴\\nfor (int i=0;i<3;i++) {\\n    resp = provider.call(req);  // 无幂等键\\n    if (ok) break;              // 立即重试，无退避\\n}\\n// 厂商已处理→重试又扣一次；100请求同时重试打垮它\";\n  var CMP=\"// ✅ 幂等 + 指数退避 + 抖动\\nif (!idempotent) throw ...;      // 没幂等不重试\\nfor (int i=0;i<maxAttempts;i++) {\\n    if (!budget.hasTime()) break; // 预算耗尽停\\n    if (!error.retryable) throw error; // 400/401不试\\n    sleep(pow(2,i)*1000 + random(0,1000)); // 退避+抖动\\n    resp = provider.call(req, idempotencyKey);\\n}\";\n  function show(k){document.getElementById(\"e7code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e7log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"重复扣费 + 重试风暴\":\"幂等防重扣，错峰防风暴\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"无幂等无退避\":\"先问幂等/预算/可重试\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e7 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e7 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：熔断状态机沙盒\n(function(){\n  var G={\n    closed:{sev:'on',title:'Closed 合闸',chips:['正常放行','统计最近100次'],\n      hint:'正常通电，请求放行，滑动窗口统计最近 100 次调用的失败率/慢调用率。',\n      log:['<span class=\"ok\">state=CLOSED，请求正常调用厂商</span>','<span class=\"c\">// 统计失败率与慢调用率</span>']},\n    open:{sev:'bad',title:'Open 跳闸',chips:['失败率>50%','快速失败'],\n      hint:'失败率超 50%（或慢调用率超 80%）→ 跳闸。此后请求快速失败，不再调用厂商，避免线程被超时占满。',\n      log:['<span class=\"err\">失败率 62% > 50% → state=OPEN</span>','<span class=\"warn\">后续请求快速失败，不调用厂商</span>','<span class=\"c\">// 保护网关自己（呼应J2线程堆积）</span>']},\n    half:{sev:'on',title:'Half-Open 试送',chips:['冷却30s到','放5个探测'],\n      hint:'Open 冷却 30 秒后转半开，只放行 5 个探测请求试探厂商是否恢复，数量受限即使没好也不造成大冲击。',\n      log:['<span class=\"api\">冷却 30s 到 → state=HALF_OPEN</span>','<span class=\"api\">放行 5 个探测请求</span>','<span class=\"c\">// 自动检测恢复，无需人工</span>']},\n    recover:{sev:'on',title:'探测成功→Closed',chips:['探测成功','恢复使用A'],\n      hint:'半开探测成功 → 认为厂商恢复，转 Closed 重新正常放行；若探测失败则回到 Open 继续断着。',\n      log:['<span class=\"ok\">5 个探测成功 → state=CLOSED</span>','<span class=\"ok\">恢复使用厂商 A</span>','<span class=\"c\">// 探测失败则回 OPEN</span>']},\n    isolate:{sev:'on',title:'按厂商隔离',chips:['A跳闸','B照常'],\n      hint:'每个厂商独立熔断器：A 挂了只断 A，B 的熔断器仍 Closed 照常工作。绝不全局误伤。',\n      log:['<span class=\"err\">breaker(openai)=OPEN</span>','<span class=\"ok\">breaker(qwen)=CLOSED，照常</span>','<span class=\"c\">// 路由发现A不健康→切B（J5）</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g7chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g7hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g7log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g7 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g7 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('closed');\n})();\n\nconst QUIZ=[{\"q\":\"1. 自动重试的前提是？\",\"opts\":[[\"操作幂等\",true,\"对。没有幂等不重试。\"],[\"速度快\",false,\"无关。\"],[\"厂商支持\",false,\"不是前提。\"]]},{\"q\":\"2. 同一幂等键用于不同请求（hash 不同）应？\",\"opts\":[[\"返回 409 IDEMPOTENCY_KEY_REUSED\",true,\"对。防止键复用。\"],[\"返回缓存结果\",false,\"那是 hash 相同。\"],[\"重新处理\",false,\"会乱。\"]]},{\"q\":\"3. 超时预算应该怎么设？\",\"opts\":[[\"总预算沿链路递减，超时取消下游\",true,\"对。用户最多等总预算。\"],[\"每层各设30秒\",false,\"最坏90秒。\"],[\"不设超时\",false,\"无法隔离。\"]]},{\"q\":\"4. 退避加抖动是为了？\",\"opts\":[[\"避免大量请求同一秒重试形成风暴\",true,\"对。错峰。\"],[\"加快重试\",false,\"恰恰相反。\"],[\"节省内存\",false,\"无关。\"]]},{\"q\":\"5. 熔断器应该怎么隔离？\",\"opts\":[[\"按厂商独立熔断器，不全局误伤\",true,\"对。A挂只断A。\"],[\"全局一个熔断器\",false,\"会误伤B。\"],[\"不隔离\",false,\"会拖垮全部。\"]]},{\"q\":\"6. 哪种错误不能故障切换？\",\"opts\":[[\"400/401/403/配额/内容安全拒绝\",true,\"对。确定性错误切了也没用。\"],[\"网络失败\",false,\"那可切。\"],[\"504超时\",false,\"那可切。\"]]}];" },
    "backend|java|消息队列与异步": { "body": "<p class=\"lead\">用户聊完，系统要记用量、写审计、更新报表。初级让用户等这三件做完才返回——像快递员非要当面交件，你不在他一直等。中级改成快递柜：投进格子就走，你有空再取，取完按「已签收」（ack）；没签收再投一次，反复没人取的挪到「问题件暂存区」（死信队列）。两个坑：取件短信可能发两遍但件只能取一次（幂等消费）；账记了快递却没投出去（双写不一致）——Outbox 让登记和记账在同一次动作里完成。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">异步化</span><span class=\"s\">快递柜解耦</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">可靠投递</span><span class=\"s\">ACK·幂等·死信</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">Outbox</span><span class=\"s\">底单本防双写</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>哪些活该异步，事件怎么设计</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 150\" role=\"img\" aria-label=\"快递柜消息流转\">\n        <defs><marker id=\"arj8\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"50\" width=\"140\" height=\"56\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"78\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">生产者</text><text x=\"78\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">投件就走</text>\n        <rect x=\"190\" y=\"50\" width=\"160\" height=\"56\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"270\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">快递柜 MQ</text><text x=\"270\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">堆积·削峰</text>\n        <rect x=\"392\" y=\"50\" width=\"150\" height=\"56\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"467\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">消费者</text><text x=\"467\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">取件→处理→ack</text>\n        <rect x=\"584\" y=\"20\" width=\"168\" height=\"44\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"668\" y=\"47\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1E7268\">入账成功→签收</text>\n        <rect x=\"584\" y=\"92\" width=\"168\" height=\"44\" rx=\"9\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"668\" y=\"119\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#B04A35\">反复失败→死信暂存</text>\n        <line x1=\"148\" y1=\"78\" x2=\"188\" y2=\"78\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj8)\"/>\n        <line x1=\"350\" y1=\"78\" x2=\"390\" y2=\"78\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj8)\"/>\n        <line x1=\"542\" y1=\"68\" x2=\"582\" y2=\"42\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj8)\"/>\n        <line x1=\"542\" y1=\"88\" x2=\"582\" y2=\"114\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj8)\"/>\n      </svg>\n      <figcaption>图 1 · 投件、取件、签收回执；反复失败的进死信暂存区，不阻塞正常消息。</figcaption>\n    </figure>\n    <p>判断标准一句话：<b>这操作必须在请求返回前完成吗？</b>配额扣减/限流必须实时 → 同步；用量流水/账单/报表可延迟 → 异步。事件驱动则是一个用量事件喂给账单+报表+风控多个消费者。</p>\n    <table>\n      <tr><th>方式</th><th>特点</th><th>网关应用</th></tr>\n      <tr><td>同步</td><td>实时强一致慢</td><td>配额扣减、限流</td></tr>\n      <tr><td>异步</td><td>解耦快最终一致</td><td>用量入账、审计</td></tr>\n      <tr><td>事件驱动</td><td>一事件多消费者</td><td>用量→账单+报表+风控</td></tr>\n    </table>\n    <p>主线选 <b>RabbitMQ</b>（原生确认/重试路由/死信，Spring AMQP 成熟），Kafka/RocketMQ 只做选型对比。事件设计三原则：<span class=\"term2\">唯一 eventId</span>（消费幂等键）、<span class=\"term2\">版本化</span>（新增字段可选，不破坏老消费者）、<span class=\"term2\">自包含</span>（发生时的快照，消费者不回查——回查时数据可能已变）。</p>\n    <div class=\"recap\"><b>收束：</b>实时控制同步、后台入账异步；事件唯一、版本化、自包含。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>可靠投递、幂等消费与 Outbox</h2>\n    <p><b>手动 ACK</b>：处理成功才签收（自动 ACK 收到就确认，处理时宕机消息就丢了）。这带来 <span class=\"term2\">At-Least-Once</span>（至少一次，可能重复）语义——所以消费端必须幂等：<code>event_id</code> 唯一约束，<b>流水插入 + 账单累加放同一本地事务</b>（否则流水成功账单失败，重投因 eventId 已存在跳过，账单永远少算）；只有 DuplicateKeyException 算重复，其他异常抛出重试；ACK 在事务提交之后。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 140\" role=\"img\" aria-label=\"Outbox 同事务落盘再投递\">\n        <defs><marker id=\"arj8b\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"34\" width=\"230\" height=\"72\" rx=\"12\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"123\" y=\"58\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1E7268\">一个本地事务</text><text x=\"123\" y=\"80\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5B4A2F\">写业务流水 + 写 outbox 底单</text><text x=\"123\" y=\"96\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">要么都成功要么都失败</text>\n        <rect x=\"290\" y=\"44\" width=\"180\" height=\"52\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"380\" y=\"66\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#8A5510\">投递员轮询</text><text x=\"380\" y=\"84\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">发成功标记 SENT</text>\n        <rect x=\"522\" y=\"44\" width=\"230\" height=\"52\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"637\" y=\"66\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">MQ → 幂等消费</text><text x=\"637\" y=\"84\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">eventId 去重 + 对账兜底</text>\n        <line x1=\"238\" y1=\"70\" x2=\"288\" y2=\"70\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj8b)\"/>\n        <line x1=\"470\" y1=\"70\" x2=\"520\" y2=\"70\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj8b)\"/>\n      </svg>\n      <figcaption>图 2 · Outbox：业务数据和待发底单同事务落盘，投递员至少一次发送，消费端幂等。</figcaption>\n    </figure>\n    <ul>\n      <li><b>重试有上限</b>：临时失败（DB 抖动）指数重试（2s→10s，max 3）；永久失败（格式错/毒消息）进<span class=\"term2\">死信队列 DLQ</span> 隔离，不阻塞正常消息；人工补偿接口可查询、修复后重处理（仍幂等）。</li>\n      <li><b>乱序</b>：用量是累加，加法可交换天然顺序无关；状态变更才需同租户同分区或序号。</li>\n      <li><b>Outbox 的边界</b>：它原子解决「DB 业务写入 + 待发事件写入」，<b>不能</b>让 Redis/DB/RabbitMQ 自动同事务，也不保证只发一次。Redis 预占成功但 DB 流水失败 → 记错误指标 + reservationId 补偿对账。</li>\n      <li><b>最终一致 + 对账</b>：请求返回时 Redis 已扣、流水可能未入账，几秒后消费者补上；定时对账 Redis vs DB 流水、requestId vs eventId，偏差修正告警，是最后防线。</li>\n    </ul>\n    <div class=\"recap\"><b>收束：</b>允许晚到账（最终一致），绝不允许重复入账或漏账；Outbox+幂等+对账兜底。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：消费写法、消息旅程</h2>\n    <p>演练一看自动 ACK 和「手动 ACK + 幂等同事务」的差别。演练二选一个消息场景，看快递柜怎么流转、账目怎么保持正确。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 消费确认写法</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e8\"><button data-k=\"api\" class=\"on\">❌ 自动 ACK</button><button data-k=\"cmp\">✅ 手动 ACK+幂等</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e8code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e8log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">ACK 必须在事务提交之后</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 消息旅程沙盒</b><span class=\"hint\">选场景，看流转与账目</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g8\"><button data-g=\"normal\" class=\"on\">正常签收</button><button data-g=\"dup\">重复投递</button><button data-g=\"crash\">ACK前宕机</button><button data-g=\"poison\">毒消息</button><button data-g=\"outbox\">双写Outbox</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g8chips\"></div><div class=\"key\" id=\"g8hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>消息日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g8log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">同一 eventId 投递 5 次，账单只加一次</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>说清「消息重复送达」时系统为什么不会多扣用户一分钱、靠什么证据证明——就是异步一致性能力。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你能说清重复投递为何不多扣钱、靠什么证明。下一课讲可观测性、压测与容量验证。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>ack</td><td>签收回执</td><td>处理完才确认</td></tr>\n      <tr><td>At-Least-Once</td><td>至少送到一次可能重复</td><td>消费端必须幂等</td></tr>\n      <tr><td>eventId</td><td>件的唯一编号</td><td>重复投递只入账一次</td></tr>\n      <tr><td>死信队列 DLQ</td><td>无人认领件暂存区</td><td>隔离毒消息留证据</td></tr>\n      <tr><td>Outbox</td><td>投递底单本</td><td>业务+事件同事务</td></tr>\n      <tr><td>对账</td><td>定期核账</td><td>最终一致的最后防线</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，RabbitMQ 主线与一致性口径以课程 README 为准；ACK/DLX/Outbox 机制对照官方文档。演练为模拟，非真实消息投递。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第八篇-消息队列与异步一致性 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档与模式</h3>\n      <ul>\n        <li><a href=\"https://www.rabbitmq.com/docs/confirms\" target=\"_blank\" rel=\"noopener\">RabbitMQ · Publisher Confirms 与 Consumer Ack</a> <span class=\"src\">— 可靠发布与手动确认</span></li>\n        <li><a href=\"https://www.rabbitmq.com/docs/dlx\" target=\"_blank\" rel=\"noopener\">RabbitMQ · Dead Letter Exchanges</a> <span class=\"src\">— 死信队列</span></li>\n        <li><a href=\"https://microservices.io/patterns/data/transactional-outbox.html\" target=\"_blank\" rel=\"noopener\">Transactional Outbox 模式</a> <span class=\"src\">— 双写一致性与最终一致</span></li>\n        <li><a href=\"https://docs.spring.io/spring-amqp/reference/\" target=\"_blank\" rel=\"noopener\">Spring AMQP · 参考文档</a> <span class=\"src\">— 手动 ACK 与重试配置</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"异步化与事件设计"},{"id":"b","title":"可靠投递与Outbox"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 自动 ACK：收到就确认，处理宕机丢消息\\n@RabbitListener(queues=\\\"usage.queue\\\")\\npublic void consume(UsageEvent e) {\\n    // 框架收到即自动 ACK\\n    process(e);   // 这里宕机 → 消息已ACK → 丢失\\n}\";\n  var CMP=\"// ✅ 手动 ACK + 幂等同事务\\n@RabbitListener(queues=\\\"usage.queue\\\", ackMode=\\\"MANUAL\\\")\\npublic void consume(UsageEvent e, Channel ch, long tag) {\\n    try {\\n        processInTx(e);      // 流水+账单同一事务, eventId去重\\n        ch.basicAck(tag,false);   // 事务提交后才签收\\n    } catch (Exception ex) {\\n        ch.basicNack(tag,false,true); // 失败重投\\n    }\\n}\";\n  function show(k){document.getElementById(\"e8code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e8log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"处理宕机 → 消息丢失漏账\":\"宕机重投 + 幂等 → 不重不漏\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"先确认后处理\":\"先处理提交后确认\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e8 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e8 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：消息旅程沙盒\n(function(){\n  var G={\n    normal:{sev:'on',title:'正常签收',chips:['投件→取件','处理→ack'],\n      hint:'生产者投件，消费者取件处理（流水+账单同事务），成功后手动 ACK，快递柜清掉这件。',\n      log:['<span class=\"api\">投递 UsageEvent(eventId=E1)</span>','<span class=\"ok\">处理：流水插入+账单累加（同事务）</span>','<span class=\"ok\">basicAck → 柜子清件</span>']},\n    dup:{sev:'on',title:'重复投递幂等',chips:['E1 投5次','只入账1次'],\n      hint:'同一 eventId 投递 5 次：第 1 次入账，后 4 次撞 event_id 唯一约束（DuplicateKeyException）跳过。账单只加一次。',\n      log:['<span class=\"api\">E1 第1次 → 入账成功</span>','<span class=\"warn\">E1 第2~5次 → 唯一约束冲突</span>','<span class=\"ok\">跳过，账单只累加一次</span>','<span class=\"c\">// 重复不产生副作用</span>']},\n    crash:{sev:'bad',title:'ACK前宕机',chips:['处理完未ACK','重投幂等'],\n      hint:'处理完成但 ACK 前宕机：消息没签收，broker 重投；重投时 eventId 已存在 → 幂等跳过，不重复入账。',\n      log:['<span class=\"ok\">处理完成（事务已提交）</span>','<span class=\"err\">ACK 前宕机 → 未签收</span>','<span class=\"api\">broker 重投 E1</span>','<span class=\"ok\">eventId 已存在 → 跳过，不重扣</span>']},\n    poison:{sev:'bad',title:'毒消息进DLQ',chips:['重试3次','死信隔离'],\n      hint:'格式损坏的毒消息谁取都报错：重试 3 次仍失败 → 进死信队列隔离，不阻塞后续正常消息；人工修复后补偿重处理（仍幂等）。',\n      log:['<span class=\"err\">毒消息处理失败 ×3（指数退避）</span>','<span class=\"warn\">超上限 → 进 DLQ 暂存</span>','<span class=\"ok\">正常消息不受阻塞</span>','<span class=\"c\">// 人工排查→补偿接口重处理</span>']},\n    outbox:{sev:'on',title:'双写Outbox',chips:['业务+底单同事务','投递员发'],\n      hint:'写业务流水和写 outbox 底单在同一本地事务（要么都成功要么都失败），投递员轮询至少一次发送，消费端 eventId 幂等。杜绝「账记了快递没投」。',\n      log:['<span class=\"ok\">事务：写流水 + 写 outbox(PENDING)</span>','<span class=\"api\">投递员轮询 → 发 MQ → 标记 SENT</span>','<span class=\"ok\">消费端 eventId 幂等入账</span>','<span class=\"c\">// 对账兜底：requestId vs eventId</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g8chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g8hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g8log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g8 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g8 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('normal');\n})();\n\nconst QUIZ=[{\"q\":\"1. 用量流水入账该同步还是异步？\",\"opts\":[[\"异步（可延迟，最终一致）\",true,\"对。配额扣减才同步。\"],[\"同步等入账完\",false,\"拖慢响应。\"],[\"都不对\",false,\"异步合适。\"]]},{\"q\":\"2. 手动 ACK 带来什么语义？\",\"opts\":[[\"At-Least-Once，可能重复需幂等\",true,\"对。至少一次。\"],[\"Exactly-Once 天然\",false,\"需幂等才等效。\"],[\"At-Most-Once\",false,\"那是自动ACK丢消息。\"]]},{\"q\":\"3. 流水插入和账单累加为什么必须同一事务？\",\"opts\":[[\"否则重投因eventId已存在跳过，账单永远少算\",true,\"对。要么一起提交一起回滚。\"],[\"性能更好\",false,\"那是一致性。\"],[\"无所谓\",false,\"会漏账。\"]]},{\"q\":\"4. 毒消息怎么处理？\",\"opts\":[[\"重试上限后进死信队列隔离\",true,\"对。不阻塞正常消息。\"],[\"无限重试\",false,\"会堵队列。\"],[\"直接丢弃\",false,\"要留证据补偿。\"]]},{\"q\":\"5. Outbox 能原子保证什么？\",\"opts\":[[\"DB业务写入+待发事件写入同事务\",true,\"对。不能让Redis/DB/MQ同事务。\"],[\"Redis和MQ同事务\",false,\"做不到。\"],[\"消息只发一次\",false,\"至少一次。\"]]},{\"q\":\"6. 最终一致的最后一道防线是？\",\"opts\":[[\"定时对账（Redis vs DB、requestId vs eventId）\",true,\"对。偏差修正告警。\"],[\"不管它\",false,\"会偏差。\"],[\"强一致同步\",false,\"那就不是最终一致了。\"]]}];" },
    "backend|java|可观测与压测": { "body": "<p class=\"lead\">车好不好，仪表盘告诉你多快、油剩多少、有没有故障灯（指标）；行车记录仪回放刚才那一下（日志）；导航轨迹告诉你 20 分钟里 15 分钟堵在哪段（链路）。上线前还得满载跑一圈（压测），才知道第一课写的「500 QPS、网关 P95 ≤ 50ms」是真的还是纸面数字。真出事的顺序：故障灯先亮（告警）→ 看轨迹定位哪段（链路）→ 回放记录仪还原这一次（日志）。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">三支柱</span><span class=\"s\">指标日志链路</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">告警</span><span class=\"s\">对应动作</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">压测</span><span class=\"s\">验证容量目标</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>三支柱：用同一个 traceId 串起来</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 150\" role=\"img\" aria-label=\"可观测性三支柱\">\n        <rect x=\"8\" y=\"30\" width=\"230\" height=\"80\" rx=\"12\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"123\" y=\"54\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2F58A8\">指标 · 仪表盘</text><text x=\"123\" y=\"76\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5B4A2F\">发现问题：快慢对错</text><text x=\"123\" y=\"94\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">RED + USE</text>\n        <rect x=\"264\" y=\"30\" width=\"230\" height=\"80\" rx=\"12\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"379\" y=\"54\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#1E7268\">链路 · 行程轨迹</text><text x=\"379\" y=\"76\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5B4A2F\">定位哪一段慢</text><text x=\"379\" y=\"94\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">Trace / Span</text>\n        <rect x=\"520\" y=\"30\" width=\"232\" height=\"80\" rx=\"12\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"636\" y=\"54\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#8A5510\">日志 · 记录仪</text><text x=\"636\" y=\"76\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5B4A2F\">还原这一次请求</text><text x=\"636\" y=\"94\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">结构化 JSON</text>\n        <text x=\"380\" y=\"135\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#A9682F\">同一个 traceId 把三者串成一条时间线</text>\n      </svg>\n      <figcaption>图 1 · 指标发现问题、链路定位哪段、日志还原现场；少一根柱子排障就得靠猜。</figcaption>\n    </figure>\n    <p>结构化日志（JSON）带统一字段 time/level/service/<b>traceId/requestId/tenantId</b> + 业务字段，用 MDC 自动注入、<code>finally MDC.clear()</code>（呼应 J3）。三个 ID 含义不同：<span class=\"term2\">requestId</span> 关联一次逻辑请求与对账、<span class=\"term2\">traceId</span> 描述一次执行链路（同一 requestId 重试可产生新 traceId）、<span class=\"term2\">eventId</span> 标识一条异步事件。HTTP 用 W3C traceparent 传播，异步把上下文写消息 Header。日志脱敏（API Key/Prompt/手机号）。</p>\n    <table>\n      <tr><th>方法</th><th>视角</th><th>三件事</th></tr>\n      <tr><td>RED</td><td>用户/请求</td><td>Rate(QPS)·Errors(错误率)·Duration(P95/P99)</td></tr>\n      <tr><td>USE</td><td>资源</td><td>Utilization(CPU/堆)·Saturation(排队/积压)·Errors</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">指标陷阱</span>Gauge 要绑定长期存活对象（临时 int 会被弱引用回收）；Timer 不默认发布分位数，Prometheus 开 histogram 用 histogram_quantile 算；<b>tenantId/requestId/traceId 等高基数字段只能进日志/Trace，不能当指标标签</b>（会撑爆时序库）。</div>\n    <div class=\"recap\"><b>收束：</b>三支柱各答一问，traceId 串线；高基数字段进日志不进指标。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>告警、压测与诚实的容量结论</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 140\" role=\"img\" aria-label=\"一个traceId串起四个Span\">\n        <text x=\"8\" y=\"24\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#5B4A2F\">traceId=trace-abc · 条越长这段越慢</text>\n        <text x=\"8\" y=\"52\" font-size=\"10.5\" fill=\"#7C7166\">Backend</text><rect x=\"90\" y=\"40\" width=\"300\" height=\"16\" rx=\"4\" fill=\"#C9D8F2\"/>\n        <text x=\"8\" y=\"76\" font-size=\"10.5\" fill=\"#7C7166\">Gateway</text><rect x=\"120\" y=\"64\" width=\"240\" height=\"16\" rx=\"4\" fill=\"#BFE0DB\"/>\n        <text x=\"8\" y=\"100\" font-size=\"10.5\" fill=\"#7C7166\">配额</text><rect x=\"130\" y=\"88\" width=\"20\" height=\"16\" rx=\"4\" fill=\"#EDD9B4\"/>\n        <text x=\"8\" y=\"124\" font-size=\"10.5\" fill=\"#7C7166\">OpenAI</text><rect x=\"160\" y=\"112\" width=\"200\" height=\"16\" rx=\"4\" fill=\"#F0CFC6\"/><text x=\"370\" y=\"124\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#B04A35\">← 70ms 最慢</text>\n        <text x=\"560\" y=\"80\" font-size=\"11\" fill=\"#5B4A2F\">厂商慢 ≠ 网关慢</text><text x=\"560\" y=\"100\" font-size=\"10.5\" fill=\"#7C7166\">要分离网关自身延迟</text>\n      </svg>\n      <figcaption>图 2 · 一个 traceId 串起多个 Span，最长的就是瓶颈段；据此区分厂商延迟与网关自身延迟。</figcaption>\n    </figure>\n    <p><b>告警要对应动作</b>，不只显异常：「P95&gt;200ms 持续 5 分钟 → 可能厂商变慢/线程池排队 → 查厂商健康 Dashboard，必要时切换 → 附 Runbook」。分级 P0（不可用，电话）/P1（错误率飙升/熔断，15 分钟）/P2（延迟略高，工作时间）；阈值基于 J1 目标（可用性&lt;99.9%→P0、网关 P95&gt;50ms 持续 5min→P1、积压&gt;10000→P1）；用持续时间/聚合/静默避免告警疲劳。</p>\n    <ul>\n      <li><b>压测要真实</b>：80% 流式 + 20% 普通、token 有长有短、持续够长、逐步加压找拐点。拿一万次「你好」压测等于空车跑高速。</li>\n      <li><b>三种延迟别混</b>：网关自身延迟（对应 P95≤50ms 目标）/ 首 Token 延迟 TTFT（用户感知）/ 完整响应时间（长对话几十秒正常）。客户端 waiting 含网络+下游，<b>不能证明网关&lt;50ms</b>，要服务端 Span 分解或 Mock 差值。</li>\n      <li><b>瓶颈用证据</b>：延迟高→链路最慢 Span→厂商慢则切换、网关慢则查 CPU(jstack)/GC/线程池/连接池。优化<b>一次只改一个变量</b>，前后对比。</li>\n      <li><b>容量结论要诚实</b>：环境+模型+指标 vs 目标+瓶颈优化+安全容量+扩容条件+风险；达标给证据、未达标说原因、没测明确说明。本地等比缩小（50 QPS/200 SSE）+ Mock 厂商标注环境。</li>\n    </ul>\n    <div class=\"recap\"><b>收束：</b>告警带动作，压测分三种延迟，瓶颈靠证据，容量结论诚实带环境。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：日志告警写法、排障定位</h2>\n    <p>演练一看非结构化日志+坏告警和结构化+好告警的差别。演练二从一条告警出发，顺着 traceId 走一遍定位。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 日志与告警</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e9\"><button data-k=\"api\" class=\"on\">❌ 纯文本+坏告警</button><button data-k=\"cmp\">✅ 结构化+好告警</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e9code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e9log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">告警要告诉值班的人该干什么</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 排障定位沙盒</b><span class=\"hint\">选告警，顺 traceId 定位</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g9\"><button data-g=\"provider\" class=\"on\">P95告警→厂商慢</button><button data-g=\"gc\">网关慢→GC</button><button data-g=\"pool\">连接池耗尽</button><button data-g=\"mq\">队列积压</button><button data-g=\"report\">容量结论</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g9chips\"></div><div class=\"key\" id=\"g9hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>排障日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g9log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">告警→链路定位→日志还原→证据优化</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>从一条告警出发，顺 traceId 找到哪段慢、为什么慢，并拿出前后对比数据——就是可观测性闭环。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你能从告警顺 traceId 定位瓶颈并拿出前后对比。下一课讲 CI/CD 与生产交付。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>结构化日志</td><td>能检索的行车记录</td><td>带 traceId/requestId</td></tr>\n      <tr><td>traceId</td><td>贯穿全程的行程编号</td><td>串起跨服务证据</td></tr>\n      <tr><td>RED / USE</td><td>用户视角/资源视角</td><td>快慢对错 / 机器饱不饱</td></tr>\n      <tr><td>Span</td><td>行程里的一小段</td><td>定位时间花在哪步</td></tr>\n      <tr><td>P95</td><td>95%请求都不比这慢</td><td>比平均值反映体验</td></tr>\n      <tr><td>容量结论</td><td>满载试车后的结论</td><td>诚实带环境与限制</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，可观测与压测口径以课程 README 为准；与第一课容量目标闭环。演练为模拟排障，非真实压测数据。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第九篇-可观测性压测与容量验证 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://opentelemetry.io/docs/\" target=\"_blank\" rel=\"noopener\">OpenTelemetry · 文档</a> <span class=\"src\">— Trace/Span 与上下文传播</span></li>\n        <li><a href=\"https://www.w3.org/TR/trace-context/\" target=\"_blank\" rel=\"noopener\">W3C · Trace Context</a> <span class=\"src\">— traceparent 跨服务传播</span></li>\n        <li><a href=\"https://prometheus.io/docs/prometheus/latest/querying/functions/\" target=\"_blank\" rel=\"noopener\">Prometheus · histogram_quantile</a> <span class=\"src\">— 分位数计算</span></li>\n        <li><a href=\"https://grafana.com/docs/k6/latest/\" target=\"_blank\" rel=\"noopener\">k6 · 压测文档</a> <span class=\"src\">— 混合场景与逐步加压</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"三支柱与上下文"},{"id":"b","title":"告警压测容量"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 纯文本日志 + 坏告警\\nlog.info(\\\"用户调用模型成功，耗时234ms\\\");\\n// 无法按字段查询/聚合/告警\\n告警: \\\"CPU 使用率 80%\\\"\\n// 然后呢？值班的人不知道该干什么\";\n  var CMP=\"// ✅ 结构化日志 + 好告警\\n{\\\"time\\\":...,\\\"traceId\\\":\\\"trace-abc\\\",\\n \\\"tenantId\\\":\\\"T001\\\",\\\"action\\\":\\\"MODEL_CALL\\\",\\n \\\"provider\\\":\\\"openai\\\",\\\"cost\\\":234,\\\"status\\\":\\\"OK\\\"}\\n告警: \\\"网关P95>200ms持续5min\\n 原因:厂商变慢/线程池排队\\n 动作:查厂商Dashboard,必要时切换 [Runbook]\\\"\";\n  function show(k){document.getElementById(\"e9code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e9log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"无法检索 + 告警无动作\":\"可按traceId查 + 告警带动作\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"排障靠猜\":\"顺traceId定位\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e9 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e9 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：排障定位沙盒\n(function(){\n  var G={\n    provider:{sev:'bad',title:'P95告警→厂商慢',chips:['链路定位','OpenAI Span 70ms'],\n      hint:'P95 告警亮 → 看链路：OpenAI Span 最长(70ms)，网关自身仅 5ms → 是厂商慢不是网关慢 → 考虑切换/超时（J7）。',\n      log:['<span class=\"err\">告警：网关P95>200ms 持续5min</span>','<span class=\"api\">traceId=trace-abc → OpenAI Span 70ms 最慢</span>','<span class=\"ok\">网关自身 5ms → 厂商问题</span>','<span class=\"c\">// 切换厂商/调超时（J7）</span>']},\n    gc:{sev:'bad',title:'网关慢→GC',chips:['USE饱和度','GC频繁'],\n      hint:'链路显示网关自身慢 → 查 USE 资源指标：GC 频率高、堆使用率高 → 看 GC 日志，调堆/减少对象创建（J2）。',\n      log:['<span class=\"err\">网关自身延迟高</span>','<span class=\"api\">USE：GC 频率↑ 堆使用率↑</span>','<span class=\"warn\">GC 日志：频繁 Full GC</span>','<span class=\"ok\">调堆大小/减少对象（J2）→ 前后对比</span>']},\n    pool:{sev:'bad',title:'连接池耗尽',chips:['HikariCP指标','等待连接'],\n      hint:'线程卡在获取连接 → HikariCP 指标 pending 排队 → 连接池不够或事务太长 → 调连接数/缩短事务（J3/J4）。',\n      log:['<span class=\"err\">请求延迟高，线程 WAITING</span>','<span class=\"api\">HikariCP：pending 排队，active 满</span>','<span class=\"ok\">缩短事务(J3)/调连接数(J4)</span>','<span class=\"c\">// 一次只改一个变量再压测</span>']},\n    mq:{sev:'bad',title:'队列积压',chips:['积压>10000','消费者不足'],\n      hint:'MQ 积压指标超 10000 → P1 告警 → 消费者处理慢或数量不足 → 增加消费者/优化消费逻辑（J8）。',\n      log:['<span class=\"err\">告警：队列积压 12000 > 10000</span>','<span class=\"api\">消费速率 < 生产速率</span>','<span class=\"ok\">增加消费者/优化消费(J8)</span>','<span class=\"c\">// 观察积压回落</span>']},\n    report:{sev:'on',title:'容量结论',chips:['vs J1目标','诚实标注'],\n      hint:'容量报告：环境+模型+指标vs目标(QPS500/网关P95 50ms/SSE2000/可用99.9%)+瓶颈优化+安全容量+扩容条件+风险。达标给证据，未达标说原因，没测说明。',\n      log:['<span class=\"api\">环境：本地等比 50QPS/200SSE + Mock</span>','<span class=\"ok\">网关P95 实测 38ms ≤ 50ms ✓</span>','<span class=\"warn\">SSE 2000 并发未测 → 明确标注</span>','<span class=\"c\">// 安全容量+扩容条件+风险</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g9chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g9hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g9log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g9 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g9 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('provider');\n})();\n\nconst QUIZ=[{\"q\":\"1. 指标、链路、日志各负责什么？\",\"opts\":[[\"发现问题/定位哪段/还原现场\",true,\"对。三支柱各答一问。\"],[\"都一样\",false,\"分工不同。\"],[\"日志最重要其他没用\",false,\"缺一不可。\"]]},{\"q\":\"2. tenantId/traceId 能当指标标签吗？\",\"opts\":[[\"不能，高基数会撑爆时序库，只进日志/Trace\",true,\"对。\"],[\"能，方便查询\",false,\"会爆炸。\"],[\"随便\",false,\"有讲究。\"]]},{\"q\":\"3. 好告警的关键是？\",\"opts\":[[\"对应明确动作和 Runbook，不只显异常\",true,\"对。告诉值班干什么。\"],[\"显示CPU80%就行\",false,\"然后呢？\"],[\"越多越好\",false,\"会告警疲劳。\"]]},{\"q\":\"4. 客户端 waiting 时间能证明网关自身<50ms 吗？\",\"opts\":[[\"不能，含网络+下游，要服务端Span分解\",true,\"对。或Mock差值。\"],[\"能\",false,\"混了厂商延迟。\"],[\"差不多\",false,\"要分离。\"]]},{\"q\":\"5. 优化时为什么一次只改一个变量？\",\"opts\":[[\"否则不知道是哪个改动起作用\",true,\"对。前后对比才可信。\"],[\"改得快\",false,\"无关。\"],[\"省事\",false,\"是为了归因。\"]]},{\"q\":\"6. 诚实的容量结论应该？\",\"opts\":[[\"达标给证据、未达标说原因、没测明确说明\",true,\"对。带环境与限制。\"],[\"只报达标项\",false,\"掩盖问题。\"],[\"不标环境\",false,\"结论不可信。\"]]}];" },
    "backend|java|CI/CD 与交付": { "body": "<p class=\"lead\">前九课把系统造好了，最后一道题：怎么安全送到用户手里，出事还能马上收回来？手工作坊是老师傅自己打包上传祈祷；工厂是流水线：零件先过几道质检（单元/契约/Review/门禁），不合格就打回；合格打成标准箱（镜像），先给 1% 门店试卖（灰度），指标没问题再放大。发现不对不是连夜改代码，而是把货架换回上一批货（回滚）——前提是新旧两批货能放同一套货架：无状态、配置外置、数据库变更向前兼容。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">测试</span><span class=\"s\">金字塔·契约</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">流水线</span><span class=\"s\">门禁不可跳过</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">灰度回滚</span><span class=\"s\">可停止可退回</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>测试金字塔、真实依赖与质量门禁</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 160\" role=\"img\" aria-label=\"测试金字塔\">\n        <polygon points=\"380,16 470,60 290,60\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"380\" y=\"48\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#B04A35\">E2E 10%</text>\n        <polygon points=\"290,64 470,64 520,108 240,108\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"380\" y=\"92\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#8A5510\">集成 20% · 真实依赖</text>\n        <polygon points=\"240,112 520,112 570,150 190,150\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"380\" y=\"138\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#1E7268\">单元 70% · 快·多·稳</text>\n        <text x=\"640\" y=\"60\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">越往上</text><text x=\"640\" y=\"78\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">越慢越贵越少</text>\n        <text x=\"120\" y=\"130\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">越往下</text><text x=\"120\" y=\"148\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#7C7166\">越快越稳越多</text>\n      </svg>\n      <figcaption>图 1 · 测试金字塔：底层单元又多又快，顶层 E2E 少而贵；集成层用真实依赖。</figcaption>\n    </figure>\n    <p><span class=\"term2\">契约测试</span>解决服务间接口不一致：消费者定契约、提供者验证符合，任一方破坏（如删字段）测试就失败，<b>上线前</b>发现，不用把两台真机器搬一起联调（Spring Cloud Contract / Pact）。<span class=\"term2\">Testcontainers</span> 用 Docker 在测试时拉起真实 MySQL/Redis/MQ，每次全新容器——J4 的 SQL/事务、J6 的 Lua 原子扣减、J8 的消息幂等，这些 <b>Mock 测不出来</b>。</p>\n    <div class=\"note\"><span class=\"tag\">质量门禁（不通过不能合并/发布）</span>编译通过 · 单元测试覆盖率&gt;70% · 集成测试通过 · 静态分析无严重问题（SonarQube）· 依赖安全扫描无高危 · 代码风格通过。把人容易漏的检查交给机器，人专注逻辑与设计。Review 清单覆盖功能/安全/一致性/韧性/可观测/测试六维。</div>\n    <div class=\"recap\"><b>收束：</b>金字塔分层、契约防接口漂移、Testcontainers 测真实行为、门禁守底线。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>流水线、向前兼容与灰度回滚</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 130\" role=\"img\" aria-label=\"CI/CD流水线与回滚通道\">\n        <defs><marker id=\"arj10\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"30\" width=\"100\" height=\"44\" rx=\"9\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"58\" y=\"57\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#2F58A8\">编译+测试</text>\n        <rect x=\"128\" y=\"30\" width=\"100\" height=\"44\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"178\" y=\"57\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#1E7268\">门禁+扫描</text>\n        <rect x=\"248\" y=\"30\" width=\"100\" height=\"44\" rx=\"9\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"298\" y=\"57\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#8A5510\">构建镜像</text>\n        <rect x=\"368\" y=\"30\" width=\"100\" height=\"44\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"418\" y=\"57\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#1E7268\">测试+冒烟</text>\n        <rect x=\"488\" y=\"30\" width=\"110\" height=\"44\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"543\" y=\"57\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#1E7268\">灰度发布</text>\n        <rect x=\"618\" y=\"30\" width=\"134\" height=\"44\" rx=\"9\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"685\" y=\"57\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#B04A35\">异常→回滚</text>\n        <line x1=\"108\" y1=\"52\" x2=\"126\" y2=\"52\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj10)\"/>\n        <line x1=\"228\" y1=\"52\" x2=\"246\" y2=\"52\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj10)\"/>\n        <line x1=\"348\" y1=\"52\" x2=\"366\" y2=\"52\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj10)\"/>\n        <line x1=\"468\" y1=\"52\" x2=\"486\" y2=\"52\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj10)\"/>\n        <line x1=\"598\" y1=\"52\" x2=\"616\" y2=\"52\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj10)\"/>\n        <text x=\"380\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#A9682F\">哪一关没过，后面拿不到制品 · 镜像标签=commit SHA 可追溯</text>\n      </svg>\n      <figcaption>图 2 · 流水线不可跳过，全量发布旁始终留一条回滚通道；产物不可变、可追溯。</figcaption>\n    </figure>\n    <p><b>配置外置</b>（代码默认&lt;配置文件&lt;环境变量&lt;配置中心），同一镜像注入不同配置；<b>密钥不进代码/镜像/日志</b>，用 Vault/KMS/Secret 运行时注入。DB 迁移用 Flyway 版本化，且<b>向前兼容</b>：加列（可空/默认）安全，删列/改列名/改类型危险（旧版崩）；大变更分步——先停用、全实例升级、下次发布再删。</p>\n    <table>\n      <tr><th>发布策略</th><th>方式</th><th>取舍</th></tr>\n      <tr><td>滚动</td><td>逐个替换实例</td><td>省资源，新旧混跑回滚慢</td></tr>\n      <tr><td>蓝绿</td><td>两套环境切换</td><td>切换/回滚快，双倍资源</td></tr>\n      <tr><td>灰度</td><td>部分流量进新版</td><td>风险可控逐步验证，实现复杂</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">自动回滚最小闭环</span>灰度 5% 观察 10 分钟。<b>继续</b>：样本足、5xx&lt;1%、P95 增幅&lt;20%、业务检查过 → 扩大。<b>停止</b>：样本不足或接近阈值 → 保持比例人工判断。<b>回滚</b>：5xx&gt;2% 持续 3min / 业务失败 / 数据兼容异常 → 新版流量降 0 → 切旧镜像 → 冒烟 → 确认告警恢复。多实例前提是无状态（配额→Redis、幂等→DB、上下文→请求级 ThreadLocal）。</div>\n    <div class=\"recap\"><b>收束：</b>产物不可变、配置分离、DB 向前兼容、发布可观测、灰度可停止、上线可回滚。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：DB 变更、灰度发布</h2>\n    <p>演练一看危险改列名和向前兼容分步的差别。演练二走一遍灰度：放流量、看指标、决定扩大还是回滚。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 数据库变更</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e10\"><button data-k=\"api\" class=\"on\">❌ 直接改列名</button><button data-k=\"cmp\">✅ 向前兼容分步</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e10code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e10log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">新旧版本要能同时跑</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 灰度发布沙盒</b><span class=\"hint\">选阶段，看流量与决策</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g10\"><button data-g=\"canary\" class=\"on\">灰度5%</button><button data-g=\"grow\">指标正常→扩大</button><button data-g=\"rollback\">5xx飙升→回滚</button><button data-g=\"hold\">样本不足→停止</button><button data-g=\"verify\">回滚后验证</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g10chips\"></div><div class=\"key\" id=\"g10hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>发布日志</span><span>live</span></div><div class=\"logcat-body\" id=\"g10log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">继续/停止/回滚都有机器可判断的条件</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>看完一条流水线，能指出哪步是质量门禁、发布后靠什么指标决定要不要回滚——就是交付能力。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。你能指出门禁在哪、靠什么指标决定回滚。最后一课把九课整合成毕业项目。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>测试金字塔</td><td>底层多快+顶层少贵</td><td>最低成本拦回归</td></tr>\n      <tr><td>契约测试</td><td>约好的插头尺寸</td><td>不联调验证接口</td></tr>\n      <tr><td>Testcontainers</td><td>临时拉真数据库来测</td><td>别拿假依赖骗自己</td></tr>\n      <tr><td>质量门禁</td><td>流水线质检关卡</td><td>不达标不许往下</td></tr>\n      <tr><td>灰度</td><td>先给1%的人试</td><td>爆炸半径最小</td></tr>\n      <tr><td>回滚</td><td>货架换回上一批货</td><td>兼容+无状态+配置外置</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，交付与发布原则以课程 README 为准；示例不绑定 Kubernetes，可用两套 Docker+Nginx 权重实验。演练为模拟发布，非真实部署。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 第十篇-CICD与生产交付 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档</h3>\n      <ul>\n        <li><a href=\"https://testcontainers.com/\" target=\"_blank\" rel=\"noopener\">Testcontainers</a> <span class=\"src\">— 真实依赖集成测试</span></li>\n        <li><a href=\"https://documentation.red-gate.com/flyway\" target=\"_blank\" rel=\"noopener\">Flyway · 数据库迁移文档</a> <span class=\"src\">— 版本化与向前兼容</span></li>\n        <li><a href=\"https://docs.github.com/en/actions\" target=\"_blank\" rel=\"noopener\">GitHub Actions · 文档</a> <span class=\"src\">— CI/CD 流水线</span></li>\n        <li><a href=\"https://spring.io/projects/spring-cloud-contract\" target=\"_blank\" rel=\"noopener\">Spring Cloud Contract</a> <span class=\"src\">— 契约测试</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"测试与质量门禁"},{"id":"b","title":"流水线与灰度回滚"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"-- ❌ 直接改列名：新旧版本都跑不了\\nALTER TABLE tenant_quota\\n  CHANGE used quota_used BIGINT;\\n-- 旧版本代码还认 used → 崩\\n-- 想回滚也回不去\";\n  var CMP=\"-- ✅ 向前兼容，分步发布\\n-- 第1步：加新列（可空/默认），旧代码当它不存在\\nALTER TABLE tenant_quota\\n  ADD COLUMN quota_used BIGINT DEFAULT 0;\\n-- 第2步：代码改用新列，确认全实例升级\\n-- 第3步：下次发布才删旧列 used\\n-- 任何时刻新旧版本都兼容\";\n  function show(k){document.getElementById(\"e10code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e10log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"旧版本崩，无法回滚\":\"新旧共存，可安全回滚\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"一步到位的危险变更\":\"加列→升级→再删，分步\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e10 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e10 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：灰度发布沙盒\n(function(){\n  var G={\n    canary:{sev:'on',title:'灰度5%',chips:['新版5%','旧版95%','观察10min'],\n      hint:'部署新版本少量实例，引入 5% 流量（或指定内部租户），用 J9 监控观察错误率/延迟，旧版承接其余 95%。',\n      log:['<span class=\"api\">部署新版本，流量 5% → 新版</span>','<span class=\"ok\">旧版承接 95%</span>','<span class=\"c\">// 观察窗口 10 分钟</span>']},\n    grow:{sev:'on',title:'指标正常→扩大',chips:['5xx<1%','P95增幅<20%','5→20→50→100'],\n      hint:'继续条件满足：样本足、5xx<1%、P95 增幅<20%、关键业务检查通过 → 逐步扩大 5%→20%→50%→100%，每档都停下看指标。',\n      log:['<span class=\"ok\">5xx 0.3% < 1%，P95 增幅 8% < 20%</span>','<span class=\"ok\">业务检查通过 → 扩大 20%</span>','<span class=\"api\">逐档 50% → 100%</span>','<span class=\"c\">// 每档观察后再放</span>']},\n    rollback:{sev:'bad',title:'5xx飙升→回滚',chips:['5xx>2%持续3min','流量降0'],\n      hint:'回滚条件触发：5xx>2% 持续 3 分钟（或业务失败/数据兼容异常）→ 新版流量降 0 → 切回旧镜像 → 冒烟 → 确认告警恢复。',\n      log:['<span class=\"err\">新版 5xx 3.5% > 2% 持续 3min</span>','<span class=\"warn\">触发回滚：新版流量 → 0</span>','<span class=\"ok\">切回旧镜像（不可变）→ 冒烟通过</span>','<span class=\"ok\">告警恢复，服务正常</span>']},\n    hold:{sev:'on',title:'样本不足→停止',chips:['样本不足','保持比例人工判断'],\n      hint:'停止条件：样本量不足或指标接近阈值 → 不盲目扩大也不急着回滚，保持当前比例，人工判断。避免误判。',\n      log:['<span class=\"warn\">10 分钟内样本仅 30 个，不足</span>','<span class=\"api\">保持 5%，不扩大</span>','<span class=\"c\">// 人工判断或延长观察</span>']},\n    verify:{sev:'on',title:'回滚后验证',chips:['旧版读新数据','冒烟+监控'],\n      hint:'回滚不是切回就完：冒烟测试关键接口、监控确认错误率/延迟正常、观察期稳定运行；DB 向前兼容保证旧版能读新版产生的数据。',\n      log:['<span class=\"ok\">冒烟：关键接口 200</span>','<span class=\"ok\">旧版读新版数据正常（向前兼容）</span>','<span class=\"ok\">监控错误率/延迟恢复</span>','<span class=\"c\">// 观察期稳定才算成功</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g10chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g10hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g10log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g10 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g10 button').forEach(function(x){x.classList.remove(\"on\");});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('canary');\n})();\n\nconst QUIZ=[{\"q\":\"1. 测试金字塔底层应该是？\",\"opts\":[[\"单元测试，又多又快又便宜\",true,\"对。70%。\"],[\"E2E 测试\",false,\"那在顶层少而贵。\"],[\"手工测试\",false,\"要自动化。\"]]},{\"q\":\"2. Testcontainers 的价值是？\",\"opts\":[[\"用真实依赖测出 Mock 测不出的行为\",true,\"对。真实SQL/Lua/MQ。\"],[\"让测试更快\",false,\"重点是真实。\"],[\"替代单元测试\",false,\"是集成层。\"]]},{\"q\":\"3. 质量门禁不通过会怎样？\",\"opts\":[[\"阻止合并/发布，后面拿不到制品\",true,\"对。不可跳过。\"],[\"警告但放行\",false,\"那就没门禁。\"],[\"人工忽略\",false,\"机器守底线。\"]]},{\"q\":\"4. 哪种数据库变更是危险的？\",\"opts\":[[\"删列/改列名/改类型（旧版崩）\",true,\"对。要分步向前兼容。\"],[\"加可空列\",false,\"那安全。\"],[\"加表\",false,\"那安全。\"]]},{\"q\":\"5. 多实例部署的前提是？\",\"opts\":[[\"无状态，状态外置到 Redis/DB\",true,\"对。任何实例处理任何请求。\"],[\"会话存实例内存\",false,\"那就不能多实例。\"],[\"单机\",false,\"无法扩展。\"]]},{\"q\":\"6. 灰度回滚的触发条件应该是？\",\"opts\":[[\"机器可判断的指标阈值（如5xx>2%持续3min）\",true,\"对。不只一句异常就回滚。\"],[\"凭感觉\",false,\"要可执行。\"],[\"永不回滚\",false,\"必须可回滚。\"]]}];" },
    "backend|java|毕业整合上线": { "body": "<p class=\"lead\">房子盖完不等于能交钥匙。验收要逐项对：水电通不通（端到端）、承重够不够（容量压测）、门锁有没有串（多租户隔离）、消防通道能不能用（回滚）。还有两件最常被跳过的事：写一本《应急手册》（Runbook）让值班的人半夜照着做就能止损；搞一次消防演习（故障注入）看手册真能用、大家真能在 10 分钟内找到起火点。演习完写事故报告（复盘），一层层问「为什么」，把改进变成有人跟、有截止时间的任务。到这里，「系统能跑」才变成「系统敢交到别人手里」。</p>\n  \n  <div class=\"journey\">\n    <div class=\"j-step\"><span class=\"n\">1</span><span class=\"t\">整合</span><span class=\"s\">十篇拼成全景</span></div>\n    <div class=\"j-step\"><span class=\"n\">2</span><span class=\"t\">验收</span><span class=\"s\">安全性能一致性</span></div>\n    <div class=\"j-step\"><span class=\"n\">3</span><span class=\"t\">演练复盘</span><span class=\"s\">Runbook·5Whys</span></div>\n    <div class=\"j-step\"><span class=\"n\">4</span><span class=\"t\">动手</span><span class=\"s\">两场演练</span></div>\n    <div class=\"j-step\"><span class=\"n\">5</span><span class=\"t\">自测</span><span class=\"s\">六个问题</span></div>\n  </div>\n\n  <section id=\"a\">\n    <h2><span class=\"no\">第 1 步</span>把十篇拼成一张全景图，逐项验收</h2>\n    <figure>\n      <svg viewBox=\"0 0 760 200\" role=\"img\" aria-label=\"十篇整合的全景架构\">\n        <rect x=\"8\" y=\"14\" width=\"744\" height=\"34\" rx=\"9\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"380\" y=\"36\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2F58A8\">接入层 · 认证授权审计（J3）· 统一协议与路由（J5）</text>\n        <rect x=\"8\" y=\"58\" width=\"240\" height=\"80\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"128\" y=\"80\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">网关核心</text><text x=\"128\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">计量配额限流（J6）</text><text x=\"128\" y=\"116\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">幂等韧性熔断（J7）</text><text x=\"128\" y=\"132\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">适配器·SSE（J5）</text>\n        <rect x=\"260\" y=\"58\" width=\"240\" height=\"80\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"380\" y=\"80\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#8A5510\">数据与中间件</text><text x=\"380\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">MySQL·Redis（J4）</text><text x=\"380\" y=\"116\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">RabbitMQ·Outbox（J8）</text><text x=\"380\" y=\"132\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">JVM·线程（J2）</text>\n        <rect x=\"512\" y=\"58\" width=\"240\" height=\"80\" rx=\"10\" fill=\"#F4F2EC\" stroke=\"#EADFD3\"/><text x=\"632\" y=\"80\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#5B4A2F\">横向守护</text><text x=\"632\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">可观测·压测（J9）</text><text x=\"632\" y=\"116\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">CI/CD·灰度回滚（J10）</text><text x=\"632\" y=\"132\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5B4A2F\">设计·ADR（J1）</text>\n        <rect x=\"8\" y=\"150\" width=\"744\" height=\"38\" rx=\"9\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"380\" y=\"174\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">一个 traceId 串起全链路：Backend→认证→配额→路由→厂商→用量事件→消费者入账</text>\n      </svg>\n      <figcaption>图 1 · 十篇拼成的完整系统；整合不是拼代码，是检查接缝——requestId 一路传、配额与入账对得上、告警指到具体环。</figcaption>\n    </figure>\n    <p>毕业篇<b>只整合、补缺、验证</b>，不引入新大块知识、不微服务化/K8s、不临时堆补丁；哪项没完成就回对应篇章解决。端到端测四条核心流程：普通对话、流式对话、配额耗尽、厂商故障切换；用一个 traceId 串起全链路（含异步消费者入账）证明整合成功。</p>\n    <table>\n      <tr><th>验收维度</th><th>对照目标（诚实报告）</th></tr>\n      <tr><td>安全（J3）</td><td>无效 Key 401 / 越权 403 / tenantId 不可伪造 / 审计独立事务脱敏</td></tr>\n      <tr><td>性能容量（J1/J9）</td><td>QPS 500 / 网关 P95≤50ms / SSE 2000 / 可用 99.9% / 切换≤30s</td></tr>\n      <tr><td>一致性（J6/7/8）</td><td>重复请求不重扣 / 重复消息不重入账 / 可对账 / 并发不超扣</td></tr>\n    </table>\n    <div class=\"recap\"><b>收束：</b>整合查接缝，验收对目标，达标给证据、未达标说原因、没测明确说明。</div>\n  </section>\n\n  <section id=\"b\">\n    <h2><span class=\"no\">第 2 步</span>多实例陷阱、Runbook 与复盘闭环</h2>\n    <p>多实例最容易踩<b>本地状态</b>三个坑：① 熔断状态别强制塞 Redis 共享（每次判断加远程依赖，Redis 故障反伤韧性）——Resilience4j 默认实例本地，全局摘除厂商用独立健康探测+路由控制面；② 限流计数器别放本地（3 实例各限 100 实际放行 300）——用 Redis 统一计数；③ 定时任务别多实例重复跑（Outbox 发送器 3 实例都发）——分布式锁或选主。</p>\n    <figure>\n      <svg viewBox=\"0 0 760 130\" role=\"img\" aria-label=\"从告警到改进项的闭环\">\n        <defs><marker id=\"arj11\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#A39B8E\"/></marker></defs>\n        <rect x=\"8\" y=\"40\" width=\"130\" height=\"50\" rx=\"10\" fill=\"#FBEDE9\" stroke=\"#F0CFC6\"/><text x=\"73\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#B04A35\">告警</text><text x=\"73\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">故障灯亮</text>\n        <rect x=\"158\" y=\"40\" width=\"130\" height=\"50\" rx=\"10\" fill=\"#FBF3E4\" stroke=\"#EDD9B4\"/><text x=\"223\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#8A5510\">Runbook 处置</text><text x=\"223\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">照着做止损</text>\n        <rect x=\"308\" y=\"40\" width=\"130\" height=\"50\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"373\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">恢复</text><text x=\"373\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">记录时长影响</text>\n        <rect x=\"458\" y=\"40\" width=\"130\" height=\"50\" rx=\"10\" fill=\"#ECF1FB\" stroke=\"#C9D8F2\"/><text x=\"523\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#2F58A8\">5 Whys 复盘</text><text x=\"523\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">问到能改的层</text>\n        <rect x=\"608\" y=\"40\" width=\"144\" height=\"50\" rx=\"10\" fill=\"#E9F4F2\" stroke=\"#BFE0DB\"/><text x=\"680\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#1E7268\">可跟踪改进项</text><text x=\"680\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"#7C7166\">负责人+截止时间</text>\n        <line x1=\"138\" y1=\"65\" x2=\"156\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj11)\"/>\n        <line x1=\"288\" y1=\"65\" x2=\"306\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj11)\"/>\n        <line x1=\"438\" y1=\"65\" x2=\"456\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj11)\"/>\n        <line x1=\"588\" y1=\"65\" x2=\"606\" y2=\"65\" stroke=\"#A39B8E\" stroke-width=\"2\" marker-end=\"url(#arj11)\"/>\n        <path d=\"M680,90 L680,112 L73,112 L73,92\" stroke=\"#2E9488\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#arj11)\"/><text x=\"380\" y=\"126\" text-anchor=\"middle\" font-size=\"10\" fill=\"#1E7268\">下次演练再验一遍，闭环</text>\n      </svg>\n      <figcaption>图 2 · 告警→Runbook 处置→恢复→5 Whys 复盘→可跟踪改进项→下次演练验证，每一步证据可串起来。</figcaption>\n    </figure>\n    <ul>\n      <li><b>Runbook</b> 每条目含：故障现象 / 可能原因 / 排查步骤（看哪个 Dashboard 查什么日志）/ 处置动作 / 升级路径（搞不定找谁）。让任何值班人员照着做，不考验临场发挥。</li>\n      <li><b>故障演练</b>至少六场景：厂商超时→熔断切换、Redis 不可用→Fail 策略、连接池耗尽→长事务/慢查询、消费者宕机积压→恢复幂等、单实例退出→不中断、灰度错误率升→回滚。每次记录预期/操作/观测/恢复/影响/改进项。</li>\n      <li><b>复盘对事不对人</b>：时间线精确到分钟、影响范围、<span class=\"term2\">5 Whys</span> 找根因（别停在「厂商慢了」，问为什么没发现/没降级/告警没响）、改进项要有负责人+截止时间可验证。</li>\n    </ul>\n    <div class=\"note\"><span class=\"tag\">毕业判定 · 中级 Lv.2</span>面对目标明确但条件复杂的模块，能分析约束、自主设计、稳定交付，并用证据证明结果达到预期。终极检验：评审者不知内部细节，仅靠文档和自动化流程从零部署→调用→压测→灰度→故障降级→回滚→Runbook 处置复盘。</div>\n    <div class=\"recap\"><b>收束：</b>能上线不算完；半夜被叫醒、照手册十分钟内定位止损，才算毕业。</div>\n  </section>\n\n  <section id=\"lab\">\n    <h2><span class=\"no\">动手</span>两场演练：复盘写法、故障演练</h2>\n    <p>演练一看空泛改进和「5 Whys + 可跟踪改进项」的差别。演练二选一个故障场景，走一遍预期→注入→观测→恢复。</p>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练一 · 事故复盘</b><span class=\"hint\">点按钮切换</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"e11\"><button data-k=\"api\" class=\"on\">❌ 空泛改进</button><button data-k=\"cmp\">✅ 5Whys+可跟踪</button></div></div>\n      <div class=\"lab-body\"><div><pre id=\"e11code\" style=\"margin:0;\"></pre></div><div class=\"logcat\"><div class=\"logcat-head\"><span>说明</span><span>live</span></div><div class=\"logcat-body\" id=\"e11log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">复盘不是找替罪羊，是让系统更健壮</span></div>\n    </div>\n    <div class=\"lab\">\n      <div class=\"lab-head\"><b>演练二 · 故障演练沙盒</b><span class=\"hint\">选场景，看预期与恢复</span></div>\n      <div class=\"controls\"><div class=\"seg\" id=\"g11\"><button data-g=\"provider\" class=\"on\">厂商超时</button><button data-g=\"redis\">Redis不可用</button><button data-g=\"consumer\">消费者宕机</button><button data-g=\"instance\">单实例退出</button><button data-g=\"canary\">灰度异常</button></div></div>\n      <div class=\"lab-body\"><div><div class=\"chips\" id=\"g11chips\"></div><div class=\"key\" id=\"g11hint\"></div></div><div class=\"logcat\"><div class=\"logcat-head\"><span>演练记录</span><span>live</span></div><div class=\"logcat-body\" id=\"g11log\"></div></div></div>\n      <div class=\"lab-foot\"><span class=\"hint\">真实注入并恢复，不是纸上演练</span></div>\n    </div>\n    <div class=\"key\"><span class=\"tag\">看懂这两场演练</span>对着全景架构图，从一条告警讲清它经过哪几环、根因在哪、下次怎么防——这就是毕业能力。</div>\n  </section>\n\n  <section id=\"quiz\">\n    <h2><span class=\"no\">自测</span>六个问题</h2>\n    <div class=\"card\" id=\"quiz-box\"></div>\n    <p id=\"quiz-done\" style=\"display:none;font-weight:700;color:#1E7268;\">全对。恭喜完成中级十一课——你已能从设计到上线对一个复杂模块负责。下一阶段：高级工程师，在不确定需求中做取舍并带团队交付。</p>\n  </section>\n\n  <section id=\"map\">\n    <h2><span class=\"no\">回顾</span>速查表</h2>\n    <table>\n      <tr><th>术语</th><th>大白话</th><th>要点</th></tr>\n      <tr><td>端到端测试</td><td>从发送到落库全走一遍</td><td>验证接缝不是单模块</td></tr>\n      <tr><td>容量验收</td><td>压测数据对目标</td><td>达标要证据</td></tr>\n      <tr><td>无状态多实例</td><td>哪台接请求都一样</td><td>才能扩容和回滚</td></tr>\n      <tr><td>Runbook</td><td>半夜照做的应急检查单</td><td>不考验临场发挥</td></tr>\n      <tr><td>故障演练</td><td>主动弄挂某依赖</td><td>验证手册告警有效</td></tr>\n      <tr><td>5 Whys</td><td>问到能改的那一层</td><td>复盘不找人背锅</td></tr>\n    </table>\n    <div class=\"note\"><span class=\"tag\">说明</span>本页为教学整理，毕业范围与判定以课程 README 为准；毕业篇只整合补缺验证，缺口回对应篇章。演练为模拟，真实演练需注入并记录恢复证据。</div>\n  </section>\n\n  <section id=\"refs\">\n    <h2><span class=\"no\">依据</span>参考链接</h2>\n    <div class=\"card refs\">\n      <h3 style=\"margin-top:0;\">原始底稿（本仓库）</h3>\n      <ul>\n        <li>《AI 后端开发：Java 实战》中级工程师 · 毕业篇-企业级AI网关整合上线 <span class=\"src\">— 本课重写底稿</span></li>\n      </ul>\n      <h3>官方文档与方法</h3>\n      <ul>\n        <li><a href=\"https://sre.google/sre-book/postmortem-culture/\" target=\"_blank\" rel=\"noopener\">Google SRE · Postmortem Culture</a> <span class=\"src\">— 对事不对人的复盘</span></li>\n        <li><a href=\"https://sre.google/workbook/on-call/\" target=\"_blank\" rel=\"noopener\">Google SRE Workbook · On-Call</a> <span class=\"src\">— Runbook 与值班处置</span></li>\n        <li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR · 架构决策记录</a> <span class=\"src\">— 决策与实现一致</span></li>\n      </ul>\n    </div>\n    \n    \n  </section>", "toc": [{"id":"a","title":"全景整合与验收"},{"id":"b","title":"多实例Runbook复盘"},{"id":"lab","title":"两场演练"},{"id":"quiz","title":"本课自测"},{"id":"map","title":"速查表"},{"id":"refs","title":"参考链接"}], "scripts": "(function(){\n  var API=\"// ❌ 空泛改进：没法跟踪等于没有\\n根因: \\\"厂商慢了\\\"\\n改进: \\\"以后要更注意监控\\\"\\n// 谁来做？什么时候？怎么验证？都没有\";\n  var CMP=\"// ✅ 5 Whys + 可跟踪改进项\\n为什么慢? → 厂商响应慢\\n为什么没切换? → 熔断阈值太高\\n为什么阈值高? → 初始配置没按实际调\\n改进(可跟踪):\\n □ 调熔断阈值 (张三, 11/30前)\\n □ 加厂商P95>100ms告警 (李四, 12/05前)\\n □ 补Runbook条目 (王五, 12/10前)\";\n  function show(k){document.getElementById(\"e11code\").textContent=(k===\"api\"?API:CMP);document.getElementById(\"e11log\").innerHTML=\"<div><span class=\\\"\"+(k===\"api\"?\"err\":\"ok\")+\"\\\">\"+(k===\"api\"?\"停在表面，无法闭环\":\"问到根因，改进可验证\")+\"</span></div><div><span class=\\\"c\\\">// \"+(k===\"api\"?\"找替罪羊\":\"对事不对人，下次演练再验\")+\"</span></div>\";}\n  document.querySelectorAll(\"#e11 button\").forEach(function(b){b.addEventListener(\"click\",function(){document.querySelectorAll(\"#e11 button\").forEach(function(x){x.classList.remove(\"on\");});b.classList.add(\"on\");show(b.getAttribute(\"data-k\"));});});\n  show(\"api\");\n})();\n\n// 演练二：故障演练沙盒\n(function(){\n  var G={\n    provider:{sev:'bad',title:'厂商超时',chips:['注入持续超时','熔断切换'],\n      hint:'预期：主厂商持续超时 → 熔断触发 → 切换备用厂商，用户无感知。观测：breaker(openai)=OPEN，请求由 qwen 处理。恢复：半开探测成功后自动回切。',\n      log:['<span class=\"api\">注入：openai 响应延迟 60s</span>','<span class=\"err\">失败率超阈值 → 熔断 OPEN</span>','<span class=\"ok\">切换 qwen，用户无感知（J7）</span>','<span class=\"ok\">恢复后探测成功 → CLOSED</span>']},\n    redis:{sev:'bad',title:'Redis不可用',chips:['注入短时宕机','Fail策略'],\n      hint:'预期：Redis 短时不可用 → 限流 Fail-Open 放行、付费配额 Fail-Closed 拒绝，都告警。观测：策略按预期执行。恢复：Redis 恢复后计数对账。',\n      log:['<span class=\"api\">注入：Redis 短时不可用</span>','<span class=\"warn\">限流 Fail-Open / 配额 Fail-Closed</span>','<span class=\"err\">告警触发，记录故障事件</span>','<span class=\"ok\">恢复后对账修正（J6）</span>']},\n    consumer:{sev:'bad',title:'消费者宕机',chips:['注入宕机积压','恢复幂等'],\n      hint:'预期：消费者宕机产生积压 → 恢复后消费积压，eventId 幂等不重复入账。观测：积压回落、账单只加一次。恢复：死信可补偿。',\n      log:['<span class=\"api\">注入：消费者宕机，消息积压</span>','<span class=\"warn\">积压上升 → P1 告警</span>','<span class=\"ok\">恢复后消费积压，eventId 去重</span>','<span class=\"ok\">账单不重复（J8）</span>']},\n    instance:{sev:'on',title:'单实例退出',chips:['杀一个实例','服务不中断'],\n      hint:'预期：杀掉一个 Gateway 实例 → 其他实例继续服务，无中断（无状态）。观测：请求随机打到存活实例结果一致。恢复：补充实例。',\n      log:['<span class=\"api\">注入：kill 一个 Gateway 实例</span>','<span class=\"ok\">流量转到存活实例</span>','<span class=\"ok\">配额在Redis/幂等共享，结果一致</span>','<span class=\"c\">// 无状态多实例（J10）</span>']},\n    canary:{sev:'bad',title:'灰度异常',chips:['注入错误率升','停止回滚'],\n      hint:'预期：灰度版本错误率明显升高 → 监控告警 → 停止灰度 → 回滚旧镜像。观测：5xx>2% 触发回滚。恢复：冒烟+监控确认服务正常。',\n      log:['<span class=\"api\">注入：灰度版本 5xx 飙升</span>','<span class=\"err\">5xx>2% 持续3min → 告警</span>','<span class=\"warn\">新版流量降0 → 切旧镜像</span>','<span class=\"ok\">冒烟+监控确认恢复（J10）</span>']}\n  };\n  function show(k){\n    var g=G[k];\n    document.getElementById('g11chips').innerHTML='<span class=\"chip '+g.sev+'\">'+g.title+'</span>'+g.chips.map(function(c){return '<span class=\"chip '+g.sev+'\">'+c+'</span>';}).join('');\n    document.getElementById('g11hint').innerHTML='<span class=\"tag\">'+g.title+'</span>'+g.hint;\n    document.getElementById('g11log').innerHTML=g.log.map(function(l){return '<div>'+l+'</div>';}).join('');\n  }\n  document.querySelectorAll('#g11 button').forEach(function(b){b.addEventListener('click',function(){\n    document.querySelectorAll('#g11 button').forEach(function(x){x.classList.remove('on');});\n    b.classList.add('on'); show(b.getAttribute('data-g'));\n  });});\n  show('provider');\n})();\n\nconst QUIZ=[{\"q\":\"1. 毕业篇的核心原则是？\",\"opts\":[[\"只整合补缺验证，缺口回对应篇章\",true,\"对。不堆补丁不引入新知识。\"],[\"学新的大块知识\",false,\"那是高级阶段。\"],[\"临时堆补丁\",false,\"掩盖设计缺陷。\"]]},{\"q\":\"2. 整合时最该检查什么？\",\"opts\":[[\"接缝：requestId一路传、配额与入账对得上\",true,\"对。不是拼代码。\"],[\"代码行数\",false,\"无关。\"],[\"界面美观\",false,\"不是重点。\"]]},{\"q\":\"3. 限流计数器放本地会怎样？\",\"opts\":[[\"3实例各限100实际放行300\",true,\"对。要Redis统一计数。\"],[\"更准确\",false,\"恰恰超放。\"],[\"没影响\",false,\"会超。\"]]},{\"q\":\"4. Runbook 的作用是？\",\"opts\":[[\"让任何值班人员照步骤处置，不考验临场发挥\",true,\"对。含排查/处置/升级路径。\"],[\"只有作者能看懂\",false,\"要别人能执行。\"],[\"装饰文档\",false,\"要可执行。\"]]},{\"q\":\"5. 5 Whys 复盘的目的是？\",\"opts\":[[\"层层问到能改的根因，对事不对人\",true,\"对。不找替罪羊。\"],[\"找谁背锅\",false,\"恰恰相反。\"],[\"停在表面原因\",false,\"要问到底。\"]]},{\"q\":\"6. 可跟踪的改进项必须？\",\"opts\":[[\"有负责人、有截止时间、可验证完成\",true,\"对。否则等于没有。\"],[\"口号式表态\",false,\"没法跟踪。\"],[\"越宏大越好\",false,\"要具体可验。\"]]}];" }
  };
  return { get: function (t, s, l) { return data[t + "|" + s + "|" + l] || null; } };
})();
